# Excel / SpreadsheetML: alcuni caratteri ASCII di controllo nei testi (es. da API SEC)
# rendono il file non valido e Excel propone il ripristino.
_EXCEL_XML_STR_MAX = 32767


def _sanitize_str_for_excel_xml(s: str, max_len: int = _EXCEL_XML_STR_MAX) -> str:
    """Rimuove caratteri non ammessi in XML 1.0 nei contenuti testuali (mantiene tab/LF/CR)."""
    if not isinstance(s, str):
        return s
    out = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", s)
    if len(out) > max_len:
        out = out[: max_len - 1] + "…"
    return out


def _sanitize_openpyxl_workbook_string_cells(wb) -> int:
    """
    Ripulisce valori stringa nelle celle prima del salvataggio openpyxl.
    Non modifica formule (data_type ``f``).
    """
    nfix = 0
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for cell in row:
                if getattr(cell, "data_type", None) == "f":
                    continue
                v = cell.value
                if not isinstance(v, str):
                    continue
                nv = _sanitize_str_for_excel_xml(v)
                if nv != v:
                    cell.value = nv
                    nfix += 1
    return nfix


