# Popolazione ristretta per (ri)stima modelli:
# includi solo relazioni sponsor–company forti da CT.gov.
_RESTRICTED_NCT_REL_ALLOWED = frozenset({
    "direct sponsor",
    "collaborator",
    "correlated company/subsidiary",
    "subsidiary",  # alias breve (stesso criterio CT.gov «correlated company/subsidiary»)
})

# Foglio «SEC K-8» — coorte = **merge Accuracy** (``_sim_rows_merged_for_accuracy_sheet``:
# futuri + passati + supplemento clinico), filtrata a sponsor **Exact/Partial** e
# ``nct_relation_type`` **≠ N/D** (vuoto escluso).


def _norm_nct_relation_label(v) -> str:
    s = str(v or "").strip().lower().replace("·", " ")
    return " ".join(s.split())


def _nct_relation_sec_k8_is_nd_or_empty(v) -> bool:
    """True se la relazione sponsor–company non è classificata (come sul foglio Accuracy da escludere)."""
    s = _norm_nct_relation_label(v)
    if not s:
        return True
    if s in ("n/d", "nd", "—", "-", "none", "nan", "n/a", "na", "null"):
        return True
    return False


def _is_sec_k8_historic_nct_relation_ok(v) -> bool:
    """Storico SEC K-8: include tutte le relazioni CT tranne N/D / vuoto (allineato alla parte Accuracy)."""
    return not _nct_relation_sec_k8_is_nd_or_empty(v)


def _is_restricted_nct_relation(v) -> bool:
    return _norm_nct_relation_label(v) in _RESTRICTED_NCT_REL_ALLOWED


def _accuracy_sheet_nct_relation_ok(v) -> bool:
    """
    Foglio **Accuracy** (e coorte storica): esclude N/D, vuoto, ``—``, ``-`` e relazioni
    diverse da direct sponsor | collaborator | correlated company/subsidiary.
    """
    return _is_restricted_nct_relation(v)


def _accuracy_cohort_nct_relation_ok(v, *, cd_past: bool) -> bool:
    """
    Coorte foglio Accuracy.

    - **Storico** (CD passata): popolazione ristretta (no N/D, no indirect).
    - **Futuro** (CD ≥ oggi): esclude solo N/D / vuoto (``indirect connections`` ammessa).
    """
    if cd_past:
        return _accuracy_sheet_nct_relation_ok(v)
    return not _nct_relation_sec_k8_is_nd_or_empty(v)


def _nct_relation_harvest_overlay_skipped(v) -> bool:
    """Non copiare da harvest→JSON valori relazione non classificati."""
    if v in (None, "", "—"):
        return True
    return _nct_relation_sec_k8_is_nd_or_empty(v)


def _sn7_ristretta_relation_ok(v) -> bool:
    """
    Coorte Ristretta CD±7 (allineata a ``ristretta_lab_data`` / Data Lab):
    relazione CT ristretta se valorizzata; se assente o N/D la riga resta eleggibile.
    """
    s = _norm_nct_relation_label(v).replace("·", " ")
    s = " ".join(s.split())
    if not s or s in ("n/d", "nd", "—", "-", "none", "nan", "n/a", "na", "null"):
        return True
    return s in _RESTRICTED_NCT_REL_ALLOWED


def _filter_records_by_restricted_nct_relation(records: list | None) -> list:
    """
    Filtra record retro/calibrazione alla popolazione ristretta richiesta:
    direct sponsor | collaborator | correlated company/subsidiary.
    Esclude N/D e qualsiasi relazione diversa.
    """
    out: list = []
    for r in (records or []):
        if not isinstance(r, dict):
            continue
        if _is_restricted_nct_relation(r.get("nct_relation_type")):
            out.append(r)
    return out


def _filter_past_pred_data_by_restricted_nct_relation(
    past_pred_data: dict | None,
) -> dict:
    out: dict = {}
    for k, r in (past_pred_data or {}).items():
        if isinstance(r, dict) and _is_restricted_nct_relation(r.get("nct_relation_type")):
            out[k] = r
    return out


def _is_exact_or_partial_sponsor_match(v) -> bool:
    return str(v or "").strip().lower() in ("exact", "partial")


def _accuracy_modello_row_in_display_cohort(dd: dict | None) -> bool:
    """
    Coorte foglio «Accuratezza Modello»:
    - sponsor **Exact** o **Partial**
    - ``nct_relation_type`` in popolazione ristretta CT.gov
      (``direct sponsor`` | ``collaborator`` | ``correlated company/subsidiary``)
    - **completion date** già passata (CD < oggi), coerente con backtest catalyst completati.
    """
    if not isinstance(dd, dict):
        return False
    if not _is_exact_or_partial_sponsor_match(dd.get("sponsor_match")):
        return False
    if not _is_restricted_nct_relation(dd.get("nct_relation_type")):
        return False
    from datetime import date as _d_today

    cd = _normalize_completion_date_ca(dd.get("completion_date"))
    if cd is None:
        return False
    return cd < _d_today.today()


def _filter_past_pred_data_for_restricted_accuracy_population(
    past_pred_data: dict | None,
) -> dict:
    """
    Popolazione richiesta per analisi/accuracy ristretta:
    - sponsor_match: Exact o Partial
    - nct_relation_type: direct sponsor | collaborator | correlated company/subsidiary
    - completion date già passata (stessa coorte del foglio «Accuratezza Modello»).
    """
    out: dict = {}
    for k, r in (past_pred_data or {}).items():
        if not isinstance(r, dict):
            continue
        if not _accuracy_modello_row_in_display_cohort(r):
            continue
        out[k] = r
    return out


def _accuracy_modello_exclude_history_window_limit(dd: dict) -> bool:
    """Stesso criterio di esclusione usato dalla sheet «Accuratezza Modello»."""
    if not isinstance(dd, dict):
        return False
    if not bool(dd.get("non_quotata_al_tempo")):
        return False
    try:
        _pre0 = int(dd.get("pre_catalyst_days") or 0) == 0
    except (TypeError, ValueError):
        _pre0 = False
    if not _pre0:
        return False
    if dd.get("price_at_cd") is not None:
        return True
    for _k in ("d1_pct", "d3_pct", "d5_pct", "d10_pct", "d30_pct",
               "model_d1_pct", "model_d3_pct", "model_d5_pct",
               "model_d10_pct", "model_d30_pct",
               "model_dm10_pct", "model_dm30_pct", "model_dm60_pct", "model_d4_pct",
               "close_m60", "close_m30", "close_m10",
               "close_m60_cal", "close_m30_cal", "close_m10_cal", "close_m4", "close_p4"):
        if dd.get(_k) is not None:
            return True
    return False


def _accuracy_modello_sheet_row_counts(past_pred_data: dict | None) -> dict:
    """
    Allinea i conteggi alla logica legacy (ex foglio Modello, rimosso dal workbook):
    righe mostrate nella sheet vs eleggibilità footer RMSE/metriche.
    """
    pdd = past_pred_data or {}
    _excluded_hist = 0
    _sorted_tks: list = []
    for k, dd in pdd.items():
        if not isinstance(dd, dict):
            continue
        if not _accuracy_modello_row_in_display_cohort(dd):
            continue
        if _accuracy_modello_exclude_history_window_limit(dd):
            _excluded_hist += 1
            continue
        _sorted_tks.append(k)
    _sorted_acc = [
        kk for kk in _sorted_tks
        if _model_accuracy_metrics_eligible(pdd.get(kk) or {})
    ]
    return {
        "sheet_rows_n": len(_sorted_tks),
        "footer_eligible_n": len(_sorted_acc),
        "excluded_fake_nonquot_n": _excluded_hist,
    }


def _build_restricted_models_population_audit(
    *,
    pp_before_relation_filter: dict | None,
    pp_after_relation_filter: dict | None,
) -> dict:
    """
    Conteggi per blocco Audit sulla sheet 📊 Modelli popolazione ristretta.
    """
    pre = pp_before_relation_filter or {}
    post = pp_after_relation_filter or {}
    strict_pop = _filter_past_pred_data_for_restricted_accuracy_population(post)
    acc_parts = _accuracy_modello_sheet_row_counts(post)
    return {
        "raw_past_pred_n": len(pre),
        "after_relation_n": len(post),
        "after_exact_partial_n": len(strict_pop),
        "accuracy_sheet_rows_n": acc_parts.get("sheet_rows_n", 0),
        "accuracy_footer_eligible_n": acc_parts.get("footer_eligible_n", 0),
        "excluded_fake_nonquot_n": acc_parts.get("excluded_fake_nonquot_n", 0),
    }

