def _financial_column_series(df: "pd.DataFrame", col_name) -> "pd.Series | None":
    """Una colonna come Series; se nomi duplicati, usa la prima occorrenza."""
    if col_name not in df.columns:
        return None
    col = df[col_name]
    if isinstance(col, pd.DataFrame):
        if col.shape[1] == 0:
            return None
        col = col.iloc[:, 0]
    if not isinstance(col, pd.Series):
        return None
    return col


def _financial_numeric_series(df: "pd.DataFrame", col_name) -> "pd.Series | None":
    """Serie numerica per stats/CF; None se colonna esclusa o non convertibile."""
    if col_name in _FINANCIAL_STATS_EXCLUDE_COLS:
        return None
    raw = _financial_column_series(df, col_name)
    if raw is None:
        return None
    return pd.to_numeric(raw, errors="coerce")

