def _orch_commit_xlsx_replace_or_stage(final_path: str, tmp_path: str, *, log_label: str) -> str:
    """
    Sposta il workbook temporaneo sul path finale con ``os.replace``.

    Se ``final_path`` è **bloccato** (tipico: Excel con il file aperto su Windows / OneDrive),
    salva accanto ``<nome>__staged_<timestamp>.xlsx`` e ne restituisce il path assoluto.
    """
    import errno as _erno
    from datetime import datetime as _dt_cx

    final_abs = os.path.abspath(final_path)
    tmp_abs = os.path.abspath(tmp_path)
    try:
        os.replace(tmp_abs, final_abs)
        return final_abs
    except (PermissionError, OSError) as ex:
        wn = getattr(ex, "winerror", None)
        en = getattr(ex, "errno", None)
        _busy = isinstance(ex, PermissionError) or wn == 32 or en in (
            _erno.EACCES, _erno.EPERM)
        if not _busy:
            raise
    stamp = _dt_cx.now().strftime("%Y%m%d_%H%M%S")
    dname, fname = os.path.split(final_abs)
    stem, ext = os.path.splitext(fname)
    fb = os.path.join(dname or ".", f"{stem}__staged_{stamp}{ext}")
    try:
        os.replace(tmp_abs, fb)
    except OSError as ex2:
        print(
            f"{log_label} Impossibile sostituire il workbook né scrivere lo staging: {ex2}",
            flush=True,
        )
        raise
    print(
        f"{log_label} Il file «{fname}» è bloccato (di solito **Excel ancora aperto**).\n"
        f"  Output completo salvato come:\n"
        f"  {fb}\n"
        f"  Apri questo file, oppure chiudi Excel sul principale e rinomina per sostituirlo.",
        flush=True,
    )
    return fb

