def _past_pred_yfinance_period() -> str:
    """
    Periodo Yahoo per ``_compute_past_catalyst_data`` / Accuratezza (più barre = Pred −60… possibili).
    Default ``10y`` (era ``5y``: troppo corto per catalyst vecchi vs «oggi»).
    Override: ``PAST_PRED_YF_PERIOD=max|10y|5y|…`` (valori yfinance).
    """
    _allowed = frozenset({
        "max", "10y", "5y", "3y", "2y", "1y", "6mo", "3mo", "2mo", "1mo", "5d", "1d",
    })
    p = os.environ.get("PAST_PRED_YF_PERIOD", "10y").strip().lower()
    return p if p in _allowed else "10y"


def _yf_download_xbi_close(yf_mod, period: str, *, cache_under: str = "^XBI") -> "pd.Series":
    """
    Benchmark biotech: Yahoo accetta spesso ^XBI; se fallisce prova «XBI» (SPDR ETF).
    Salva sempre sotto ``cache_under`` nella price cache (coerenza col resto del codice).
    """
    last_err: Exception | None = None
    for sym in ("^XBI", "XBI"):
        try:
            raw = yf_mod.download(
                sym, period=period, auto_adjust=True, progress=False,
            )
            if raw is None or getattr(raw, "empty", True):
                continue
            ser = (raw["Close"] if "Close" in raw.columns else raw.iloc[:, 0]).dropna()
            if getattr(ser, "empty", True):
                continue
            if hasattr(ser.index, "tz"):
                ser.index = pd.to_datetime(ser.index).tz_localize(None)
            _pcache_save(cache_under, ser, period)
            if sym != cache_under:
                print(f"[PriceCache] {cache_under}: usata serie Yahoo «{sym}» (fallback ETF).",
                      flush=True)
            return ser
        except Exception as _e:
            last_err = _e
            continue
    if last_err:
        print(f"[PriceCache] {cache_under} period={period} download KO: {last_err}",
              flush=True)
    return pd.Series(dtype=float)


