def _phase_numbers_min_max(val) -> tuple[int, int] | None:
    """Estrae fasi 1–4 da testo (Phase 1, 2/3, …). Ritorna (min, max) o None."""
    if val is None:
        return None
    try:
        if pd.isnull(val):
            return None
    except (TypeError, ValueError):
        pass
    s = str(val).strip()
    if not s or s.upper() in ("N/D", "NAN", "NONE"):
        return None
    nums = sorted({int(x) for x in re.findall(r"\b([1-4])\b", s.lower())})
    if not nums:
        return None
    return nums[0], nums[-1]


def _phase_study_matches_row_tier(study_phase: str, row_phase: str) -> bool:
    """
    Allinea NCT alla fase della riga: stessa «scala» massima (es. riga Ph I → solo studi Ph I).
    Se la riga non ha fase, non filtra. Se lo studio non ha fase esplicita, esclude (evita mix).
    """
    r = _phase_numbers_min_max(row_phase)
    s = _phase_numbers_min_max(study_phase)
    if r is None:
        return True
    if s is None:
        return False
    return s[1] == r[1]


def _row_phase_tier_max(row_phase: str) -> int | None:
    t = _phase_numbers_min_max(row_phase)
    return None if t is None else t[1]


def _parse_sheet_study_completion_ddmmyyyy(val):
    """Converte «Completion Date» delle righe dettaglio (DD/MM/YYYY o ISO)."""
    from datetime import datetime as _dtm
    if val is None or (isinstance(val, float) and pd.isnull(val)):
        return None
    s = str(val).strip()
    if not s or s.upper() == "N/D":
        return None
    cand = s[:10]
    for _fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            return _dtm.strptime(cand, _fmt).date()
        except ValueError:
            continue
    return _normalize_completion_date_ca(val)


def _sim_submenu_completion_match(
    row_cd,
    study_cd,
    *,
    max_days: int | None = None,
) -> bool:
    """
    True se data catalyst Simulation e data Completion dello studio coincidono o |Δ|≤tolleranza
    (giorni calendario). Evita sottomenù vuoti per differenze di 1 giorno/API.
    """
    from datetime import date as _date_t
    if row_cd is None or study_cd is None:
        return False
    if not isinstance(row_cd, _date_t) or not isinstance(study_cd, _date_t):
        return False
    _mx = int(max_days if max_days is not None else SIM_CLINICAL_SUBMENU_DATE_TOLERANCE_DAYS)
    if row_cd == study_cd:
        return True
    try:
        return abs((row_cd - study_cd).days) <= _mx
    except Exception:
        return False


def _nct_lookup_for_completati_row(ticker_studies: dict | None, row_dict: dict,
                                    max_near_days: int = 120) -> str:
    """NCT ID (match data completion riga ± max_near_days) da studi collassati."""
    tk = str(row_dict.get("ticker") or "").strip().upper()
    cd = _normalize_completion_date_ca(row_dict.get("completion_date"))
    if not tk or not cd or not ticker_studies:
        return ""

    lst = ticker_studies.get(tk) or []
    _row_ph = row_dict.get("phase")

    exact = ""
    fallback = ""
    best_d = None
    for study in lst:
        if not _phase_study_matches_row_tier(study.get("Phase", ""), _row_ph):
            continue
        nct = str(study.get("NCT ID") or "").strip().upper()
        if not (nct.startswith("NCT") and len(nct) >= 9):
            continue
        sc = _parse_sheet_study_completion_ddmmyyyy(study.get("Completion Date"))
        if sc == cd:
            exact = nct
            break
        if sc is None:
            continue
        nd = abs((sc - cd).days)
        if nd == 0:
            exact = nct
            break
        if best_d is None or nd < best_d:
            best_d = nd
            fallback = nct
    if exact:
        return exact
    if fallback and best_d is not None and best_d <= max_near_days:
        return fallback
    return ""


def _fetch_ctgov_study_json(nct_clean: str) -> dict | None:
    """Un record studio da CT.gov API v2 (query.term=NCT…) — primo match exact nctId."""
    import urllib.parse as _up
    import urllib.request as _urq
    from urllib.error import HTTPError, URLError

    nct_u = nct_clean.strip().upper()
    if not nct_u.startswith("NCT"):
        return None
    url = (_CTGOV_API_V2_STUDIES + "?query.term="
           + _up.quote(nct_u, safe="") + "&pageSize=5")
    req = _urq.Request(
        url,
        headers={
            "User-Agent": "BiotechOrchestrator/1.0 (+educational; clinicaltrials.gov)",
            "Accept": "application/json",
        },
    )
    try:
        raw = _urq.urlopen(req, timeout=28).read()
        payload = json.loads(raw.decode("utf-8", errors="replace"))
    except (HTTPError, URLError, json.JSONDecodeError, TimeoutError, OSError) as _efe:
        print(f"[CT.gov] Fetch {nct_u}: {_efe}")
        return None
    for cand in payload.get("studies") or []:
        prot = cand.get("protocolSection") or {}
        ident = prot.get("identificationModule") or {}
        nid = str(ident.get("nctId") or "").strip().upper()
        if nid == nct_u:
            return cand
    return None


def _ctgov_esito_from_study(study: dict | None) -> dict:
    """
    Dati strutturati + sintesi testuale da un record ClinicalTrials.gov API v2.

    Chiavi: overall_raw (str API), overall_it (etichetta), has_results (True/False/None),
            summary (testo sintetico). has_results è None se il campo JSON non è presente.
    """
    if not study:
        return {
            "overall_raw": "",
            "overall_it": "—",
            "has_results": None,
            "summary": "Non trovato su ClinicalTrials.gov API v2.",
        }

    prot = study.get("protocolSection") or {}
    stat_mod = prot.get("statusModule") or {}
    overall_raw = str(stat_mod.get("overallStatus") or "").strip()
    overall_it = (_CT_OVERALL_IT.get(overall_raw, overall_raw)
                  if overall_raw else "—")
    bits = [f"Stato: {overall_it}"]

    why = str(stat_mod.get("whyStopped") or "").strip()
    if why:
        bits.append(f"Stop: {why[:120]}")
        if len(why) > 120:
            bits[-1] += "…"

    if "hasResults" in study:
        has_res = bool(study["hasResults"])
        bits.append("Tabella risultati CT.gov: " + ("presente" if has_res else "assente"))
    else:
        has_res = None
        bits.append("Tabella risultati CT.gov: non indicato dall’API")

    rs = study.get("resultsSection")
    if isinstance(rs, dict):
        om = rs.get("outcomeMeasuresModule") or {}
        for key in ("outcomeMeasures", "outcomeMeasuresList"):
            mea = om.get(key)
            if isinstance(mea, list) and mea:
                ttl = []
                for m in mea[:2]:
                    if not isinstance(m, dict):
                        continue
                    t = str(m.get("title") or m.get("type") or "").strip()
                    if t:
                        ttl.append(t[:140])
                if ttl:
                    bits.append("Esiti riportati: " + " | ".join(ttl))
                    if len(bits[-1]) > 220:
                        bits[-1] = bits[-1][:217] + "…"
                break

    txt = " · ".join(bits)
    if len(txt) > _CT_ESITO_SUMMARY_CAP:
        txt = txt[: _CT_ESITO_SUMMARY_CAP - 1] + "…"
    return {
        "overall_raw": overall_raw,
        "overall_it": overall_it,
        "has_results": has_res,
        "summary": txt,
    }


def _summarize_ctgov_esito_payload(study: dict | None) -> str:
    """Testo breve stato + disponibilità risultati (+ anteprima outcome se presente)."""
    return _ctgov_esito_from_study(study)["summary"]


_CT_SEC_RESULTS_FIELD_CAP = 8000  # per colonna Excel (foglio SEC)


def _ctgov_join_unique(items: list[str], cap: int = _CT_SEC_RESULTS_FIELD_CAP) -> str:
    seen: set[str] = set()
    out: list[str] = []
    for x in items:
        t = str(x or "").strip()
        if not t or t in seen:
            continue
        seen.add(t)
        out.append(t)
    s = " | ".join(out)
    if len(s) > cap:
        return s[: cap - 1] + "…"
    return s


def _ctgov_study_results_excel_fields(study: dict | None, *, nct_id: str) -> dict[str, str]:
    """
    Estrae testi per il foglio SEC da ``resultsSection`` ClinicalTrials.gov API v2.

    Il file ``data.sec.gov/submissions/CIK…json`` **non** contiene questi campi; servono
    NCT + API CT.gov. Qui si aggregano endpoint, p-value, HR (Cox), AE/SAE e baseline.
    """
    nct_u = str(nct_id or "").strip().upper()
    url = f"https://clinicaltrials.gov/study/{nct_u}" if nct_u.startswith("NCT") else "—"
    empty = {
        "nct_id": nct_u if nct_u.startswith("NCT") else "—",
        "ctgov_url": url,
        "results_published": "—",
        "primary_endpoints": "—",
        "secondary_endpoints": "—",
        "p_values": "—",
        "hazard_ratios": "—",
        "adverse_events": "—",
        "serious_adverse_events": "—",
        "baseline_characteristics": "—",
    }
    if not study:
        return empty

    if "hasResults" in study:
        empty["results_published"] = "Sì" if study["hasResults"] else "No"
    rs = study.get("resultsSection")
    if not isinstance(rs, dict):
        return empty

    om = rs.get("outcomeMeasuresModule") or {}
    measures = om.get("outcomeMeasures")
    if not isinstance(measures, list):
        measures = []

    prim: list[str] = []
    sec: list[str] = []
    pvals: list[str] = []
    hazards: list[str] = []

    for m in measures:
        if not isinstance(m, dict):
            continue
        typ = str(m.get("type") or "").strip().upper()
        title = str(m.get("title") or "").strip()
        if not title:
            title = str(m.get("type") or "").strip() or "—"
        if typ == "PRIMARY":
            prim.append(title)
        elif typ == "SECONDARY":
            sec.append(title)

        for a in m.get("analyses") or []:
            if not isinstance(a, dict):
                continue
            pv = a.get("pValue")
            if pv is not None and str(pv).strip():
                pvals.append(f"{title[:120]}: p={pv}".strip())
            pt = str(a.get("paramType") or "").upper()
            pv_hr = str(a.get("paramValue") or "").strip()
            if pv_hr and ("COX" in pt or "HAZARD" in pt):
                ci_lo = str(a.get("ciLowerLimit") or "").strip()
                ci_hi = str(a.get("ciUpperLimit") or "").strip()
                pvv = str(a.get("pValue") or "").strip()
                hr_line = f"{title[:100]}: HR={pv_hr}"
                if ci_lo and ci_hi:
                    hr_line += f" (95% CI {ci_lo}-{ci_hi})"
                if pvv:
                    hr_line += f", p={pvv}"
                hazards.append(hr_line)

    if measures and empty["results_published"] == "—":
        empty["results_published"] = "Sì (sezione risultati presente)"

    ae_mod = rs.get("adverseEventsModule") or {}

    def _ae_lines(events: list, *, max_terms: int = 12) -> list[str]:
        lines: list[str] = []
        if not isinstance(events, list):
            return lines
        for ev in events[:max_terms]:
            if not isinstance(ev, dict):
                continue
            term = str(ev.get("term") or "").strip()
            if not term:
                continue
            stats = ev.get("stats") or []
            aff: list[str] = []
            if isinstance(stats, list):
                for st in stats:
                    if not isinstance(st, dict):
                        continue
                    na = st.get("numAffected")
                    if na is not None:
                        aff.append(str(na))
            if aff:
                lines.append(f"{term} (n affetti/gruppo: {', '.join(aff)})")
            else:
                lines.append(term)
        return lines

    oth = ae_mod.get("otherEvents") or []
    ser = ae_mod.get("seriousEvents") or []
    empty["adverse_events"] = _ctgov_join_unique(_ae_lines(oth)) or "—"
    empty["serious_adverse_events"] = _ctgov_join_unique(_ae_lines(ser)) or "—"

    bl = rs.get("baselineCharacteristicsModule") or {}
    bl_bits: list[str] = []
    for meas in (bl.get("measures") or [])[:8]:
        if not isinstance(meas, dict):
            continue
        bt = str(meas.get("title") or "").strip()
        if not bt:
            continue
        classes = meas.get("classes") or []
        row_txt: list[str] = []
        if isinstance(classes, list) and classes:
            cats = (classes[0].get("categories") or [])[:4]
            for cat in cats:
                if not isinstance(cat, dict):
                    continue
                ct = str(cat.get("title") or "").strip()
                if not ct:
                    continue
                ms = cat.get("measurements") or []
                vals: list[str] = []
                if isinstance(ms, list):
                    for mm in ms[:4]:
                        if not isinstance(mm, dict):
                            continue
                        vals.append(str(mm.get("value") or "").strip())
                if vals:
                    row_txt.append(f"{ct}: {', '.join(vals)}")
                else:
                    row_txt.append(ct)
        if row_txt:
            bl_bits.append(bt + " — " + "; ".join(row_txt[:6]))
        else:
            bl_bits.append(bt)
    empty["baseline_characteristics"] = _ctgov_join_unique(bl_bits) or "—"

    empty["primary_endpoints"] = _ctgov_join_unique(prim) or "—"
    empty["secondary_endpoints"] = _ctgov_join_unique(sec) or "—"
    empty["p_values"] = _ctgov_join_unique(pvals) or "—"
    empty["hazard_ratios"] = _ctgov_join_unique(hazards) or "—"

    return empty


def _empty_ctgov_bundle() -> dict:
    return {
        "overall_raw": "",
        "overall_it": "—",
        "has_results": None,
        "summary": "—",
    }


def _env_flag_truthy(name: str) -> bool:
    return os.environ.get(name, "").strip().lower() in ("1", "true", "yes", "on")


def _ctgov_esito_max_age_sec_env() -> float | None:
    """Se impostato (CTGOV_ESITO_MAX_AGE_DAYS), forza refresh dopo N giorni (tutte le righe cache)."""
    raw = os.environ.get("CTGOV_ESITO_MAX_AGE_DAYS", "").strip()
    if not raw:
        return None
    try:
        return max(86400.0, float(raw.replace(",", ".")) * 86400.0)
    except ValueError:
        return None


def _ctgov_cached_lab_dict(data: dict) -> dict:
    hr = data.get("has_results")
    if hr is not None:
        hr = bool(hr)
    return {
        "overall_raw": str(data.get("overall_raw") or ""),
        "overall_it": str(data.get("overall_it") or "—"),
        "has_results": hr,
        "summary": str(data.get("summary") or "—"),
    }


def _ctgov_lab_summary_is_not_found(lab: dict) -> bool:
    return (
        "non trovato su clinicaltrials.gov"
        in str(lab.get("summary") or "").lower()
    )


def _cached_ctgov_esito_bundle(nct: str) -> dict:
    """Cache disco JSON persistente + retry raro solo per trial «non trovato».

    Override: FORCE_CTGOV_ESITO_REFRESH=1 rifà il fetch ignorando cache.
           CTGOV_ESITO_MAX_AGE_DAYS=N — scadenza massima giorni per qualsiasi entry.
           CTGOV_NOT_FOUND_RETRY_DAYS — giorni prima di ripetere la query dopo «non trovato» (default 90).
    """
    nct_clean = str(nct or "").strip().upper()
    if not nct_clean.startswith("NCT"):
        return _empty_ctgov_bundle()

    os.makedirs(_CTGOV_ESITO_CACHE_DIR, exist_ok=True)
    safe = "".join(ch for ch in nct_clean if ch.isalnum())
    jpath = os.path.join(_CTGOV_ESITO_CACHE_DIR, f"{safe}.json")
    txt_path = os.path.join(_CTGOV_ESITO_CACHE_DIR, f"{safe}.txt")
    _force = _env_flag_truthy("FORCE_CTGOV_ESITO_REFRESH")
    _max_age = _ctgov_esito_max_age_sec_env()

    if os.path.isfile(jpath) and not _force:
        try:
            data = json.loads(
                pathlib.Path(jpath).read_text(encoding="utf-8", errors="replace"))
            if isinstance(data, dict) and "summary" in data:
                lab = _ctgov_cached_lab_dict(data)
                age = time.time() - os.path.getmtime(jpath)
                if _max_age is not None and age > _max_age:
                    pass
                elif _ctgov_lab_summary_is_not_found(lab):
                    if age < _CTGOV_NOT_FOUND_RETRY_SEC:
                        return lab
                else:
                    return lab
        except Exception:
            pass

    # Fallback cache legacy (.txt solo sintesi): non scade — non perdiamo testo salvato.
    if os.path.isfile(txt_path) and not os.path.isfile(jpath) and not _force:
        try:
            _sx = pathlib.Path(txt_path).read_text(
                encoding="utf-8", errors="replace").strip() or "—"
            return dict(_empty_ctgov_bundle(), summary=_sx)
        except Exception:
            pass

    body = _fetch_ctgov_study_json(nct_clean)
    lab = _ctgov_esito_from_study(body)
    try:
        _dump = {
            "overall_raw": lab["overall_raw"],
            "overall_it": lab["overall_it"],
            "has_results": lab["has_results"],
            "summary": lab["summary"],
        }
        pathlib.Path(jpath).write_text(
            json.dumps(_dump, ensure_ascii=False, indent=0),
            encoding="utf-8",
        )
    except Exception as _cw:
        print(f"[CT.gov] Cache JSON write {nct_clean}: {_cw}")
    time.sleep(_CT_ESITO_FETCH_PAUSE_S)
    return lab


def _cached_ctgov_esito_summary(nct: str) -> str:
    """Compat: sintesi dalla cache/struttura."""
    return _cached_ctgov_esito_bundle(nct)["summary"]


def _ctgov_sponsor_network_from_study(study: dict | None) -> dict:
    """Estrae lead/responsible/collaborators dal record CT.gov v2."""
    if not isinstance(study, dict):
        return {"lead_sponsor": "", "responsible_party_org": "", "collaborators": []}
    prot = study.get("protocolSection") or {}
    scm = prot.get("sponsorCollaboratorsModule") or {}
    lead = str((scm.get("leadSponsor") or {}).get("name") or "").strip()
    resp = str((scm.get("responsibleParty") or {}).get("investigatorAffiliation") or "").strip()
    collabs = []
    for cc in (scm.get("collaborators") or []):
        if not isinstance(cc, dict):
            continue
        nm = str(cc.get("name") or "").strip()
        if nm:
            collabs.append(nm)
    return {
        "lead_sponsor": lead,
        "responsible_party_org": resp,
        "collaborators": collabs,
    }


def _cached_ctgov_sponsor_network(nct: str) -> dict:
    """Cache disco sponsor network per NCT (CT.gov API v2)."""
    nct_clean = str(nct or "").strip().upper()
    if not nct_clean.startswith("NCT"):
        return {"lead_sponsor": "", "responsible_party_org": "", "collaborators": []}
    os.makedirs(_CTGOV_ESITO_CACHE_DIR, exist_ok=True)
    safe = "".join(ch for ch in nct_clean if ch.isalnum())
    jpath = os.path.join(_CTGOV_ESITO_CACHE_DIR, f"{safe}_sponsor_net.json")
    _force = _env_flag_truthy("FORCE_CTGOV_ESITO_REFRESH")
    # Di default evita fetch live (può bloccare il run su reti lente/instabili).
    # Abilita esplicitamente con CTGOV_SPONSOR_NETWORK_ALLOW_LIVE=1.
    _allow_live = _env_flag_truthy("CTGOV_SPONSOR_NETWORK_ALLOW_LIVE")
    if os.path.isfile(jpath) and not _force:
        try:
            data = json.loads(pathlib.Path(jpath).read_text(encoding="utf-8", errors="replace"))
            if isinstance(data, dict):
                out = {
                    "lead_sponsor": str(data.get("lead_sponsor") or "").strip(),
                    "responsible_party_org": str(data.get("responsible_party_org") or "").strip(),
                    "collaborators": [
                        str(x).strip()
                        for x in (data.get("collaborators") or [])
                        if str(x).strip()
                    ],
                }
                return out
        except Exception:
            pass
    if not (_allow_live or _force):
        return {"lead_sponsor": "", "responsible_party_org": "", "collaborators": []}

    body = _fetch_ctgov_study_json(nct_clean)
    out = _ctgov_sponsor_network_from_study(body)
    try:
        pathlib.Path(jpath).write_text(
            json.dumps(out, ensure_ascii=False, indent=0),
            encoding="utf-8",
        )
    except Exception:
        pass
    time.sleep(_CT_ESITO_FETCH_PAUSE_S)
    return out


def _fda_intervention_query_token(interventions_txt: str) -> str:
    """Primo token utile da interventions (brand/molecule) per ricerca OpenFDA."""
    if not interventions_txt or str(interventions_txt).strip().upper() in ("N/D", ""):
        return ""
    chunk = str(interventions_txt).split(",")[0].strip()
    for prefix in ("Drug:", "Biological:", "Device:", "Procedure:", "Radiation:"):
        if chunk.lower().startswith(prefix.lower()):
            chunk = chunk[len(prefix):].strip()
            break
    for w in re.split(r"\s+", chunk):
        w = w.strip(" '\"()[]")
        if len(w) >= 3 and re.match(r"^[A-Za-z][A-Za-z0-9\-]+$", w):
            return w[:48]
    return ""


def _parse_fda_date_flex(val) -> date | None:
    from datetime import datetime as _dtm
    s = str(val or "").strip()
    if not s:
        return None
    for fmt, sl in (("%Y-%m-%d", 10), ("%Y%m%d", 8)):
        try:
            return _dtm.strptime(s[:sl], fmt).date()
        except ValueError:
            continue
    return None


def _openfda_drugsfda_query(search: str, limit: int = 8) -> dict | None:
    import urllib.parse as _up
    import urllib.request as _urq
    from urllib.error import HTTPError, URLError

    q = _up.urlencode({"search": search, "limit": str(limit)})
    url = f"{_OPENFDA_DRUGSFDA_URL}?{q}"
    req = _urq.Request(
        url,
        headers={"User-Agent": "BiotechOrchestrator/1.0 (openFDA educational research)"},
    )
    try:
        raw = _urq.urlopen(req, timeout=28).read()
        return json.loads(raw.decode("utf-8", errors="replace"))
    except (HTTPError, URLError, json.JSONDecodeError, TimeoutError, OSError) as _efe:
        print(f"[OpenFDA] drugsfda: {_efe}")
        return None


def _earliest_ap_date_from_drugsfda(payload: dict | None) -> date | None:
    """Data submission_status=AP più antica nei risultati (best-effort)."""
    from datetime import date as _dac
    best: _dac | None = None
    if not payload or not isinstance(payload.get("results"), list):
        return None
    for res in payload["results"]:
        for sub in res.get("submissions") or []:
            st = str(sub.get("submission_status") or "").strip().upper()
            if st != "AP":
                continue
            d = _parse_fda_date_flex(sub.get("submission_status_date"))
            if d is None:
                continue
            if best is None or d < best:
                best = d
    return best


def _fda_hint_bundle(drug_token: str, sponsor_company: str) -> dict:
    """
    Cache sticky JSON: data approvazione Drugs@FDA se trovata (submission AP).
    FORCE_OPENFDA_REFRESH=1 per rifare la query.
    """
    drug_token = (drug_token or "").strip()[:64]
    sponsor_company = (sponsor_company or "").strip()[:120]
    key_src = f"{drug_token.lower()}|{sponsor_company.lower()}"
    key = hashlib.sha256(key_src.encode("utf-8")).hexdigest()[:28]
    os.makedirs(_FDA_HINT_CACHE_DIR, exist_ok=True)
    path = os.path.join(_FDA_HINT_CACHE_DIR, f"{key}.json")
    force = _env_flag_truthy("FORCE_OPENFDA_REFRESH")
    if not force and os.path.isfile(path):
        try:
            return json.loads(
                pathlib.Path(path).read_text(encoding="utf-8", errors="replace"))
        except Exception:
            pass

    ap_date = None
    if len(drug_token) >= 3:
        dt = drug_token.replace('"', "").replace("/", " ")
        pl = _openfda_drugsfda_query(
            f'openfda.brand_name:"{dt}"+OR+openfda.generic_name:"{dt}"', 12)
        ap_date = _earliest_ap_date_from_drugsfda(pl)

    if ap_date is None and sponsor_company:
        sparts = re.split(r"[\s,&]+", sponsor_company.strip())
        for sp in sparts:
            sp_clean = "".join(ch for ch in sp if ch.isalnum() or ch in " &-")
            sp_clean = sp_clean.replace('"', "").strip()
            if len(sp_clean) < 4:
                continue
            pl2 = _openfda_drugsfda_query(f'sponsor_name:"{sp_clean}*"', 8)
            ap_date = _earliest_ap_date_from_drugsfda(pl2)
            if ap_date is not None:
                break

    bundle = {
        "approval_iso": ap_date.isoformat() if ap_date else None,
        "drug_token": drug_token,
        "sponsor_hint": sponsor_company[:80],
    }
    try:
        pathlib.Path(path).write_text(
            json.dumps(bundle, ensure_ascii=False), encoding="utf-8")
    except Exception as _fw:
        print(f"[OpenFDA] Cache write: {_fw}")
    time.sleep(_FDA_FETCH_PAUSE_S)
    return bundle


def _completati_study_aligned(ticker_studies: dict | None, ticker_upper: str,
                               nct: str, row_phase) -> dict | None:
    """Studio in ticker_studies con NCT+fase congrua alla riga Completati."""
    ts = ticker_studies if ticker_studies is not None else {}
    nid = (nct or "").strip().upper()
    if not nid.startswith("NCT"):
        return None
    tk = str(ticker_upper or "").strip().upper()
    for st in ts.get(tk) or []:
        if str(st.get("NCT ID") or "").strip().upper() != nid:
            continue
        if not _phase_study_matches_row_tier(st.get("Phase", ""), row_phase):
            continue
        return st
    return None


def _clinical_polarity_hint(txt: str) -> str:
    """
    Euristica leggera su esito clinico (EN/IT): pos | neg | mix | unk.
    «mix» = segnali positivi e negativi nello stesso testo.
    """
    s = str(txt or "").strip()
    if len(s) < 16:
        return "unk"
    t = s.lower()
    pos_kw = (
        "met primary", "met the primary", "primary endpoint", "positive outcome",
        "statistically significant", "significantly improved", "significant improvement",
        "superiority", "superior to", "non-inferior", "noninferior", "non inferior",
        "efficacious", "demonstrated efficacy", "therapeutic benefit", "favorable",
        "favourable", "successful", "achieved the", "meets the primary",
        "superiorità", "significativamente", "endpoint primario", "esito positivo",
        "beneficio clinico", "miglioramento",
    )
    neg_kw = (
        "did not meet", "failed to meet", "did not achieve", "negative outcome",
        "no statistically significant", "not statistically significant",
        "statistically insignificant", "failed to demonstrate", "lack of efficacy",
        "halted due to futility", "stopped for futility", "terminated early",
        "inferiority", "did not improve", "no significant difference",
        "non ha raggiunto", "non significativo", "assenza di efficacia",
        "interruzione anticipata", "fallimento", "inefficace",
    )
    ph, nh = 0, 0
    for k in pos_kw:
        if k in t:
            ph += 1
    for k in neg_kw:
        if k in t:
            nh += 1
    if ph and nh:
        return "mix"
    if ph:
        return "pos"
    if nh:
        return "neg"
    return "unk"


def _fda_outcome_bucket(fda_txt: str) -> str:
    """Regolatorio da cella FDA: app | silent | nd."""
    ft = str(fda_txt or "").strip()
    if not ft or ft.startswith("N/D"):
        return "nd"
    if ft.startswith("Approvazione"):
        return "app"
    return "silent"


def _qualita_fonti_esito(
    *,
    has_pubmed: bool,
    has_ct: bool,
    has_fda: bool,
    pubmed_text: str,
    ct_text: str,
    fda_text: str,
) -> str:
    """
    Conteggio fonti attive e giudizio concordanza (euristica testuale / regolatorio).
    """
    n_max = 3
    flags = [has_pubmed, has_ct, has_fda]
    n_have = sum(1 for x in flags if x)
    if n_have == 0:
        return f"0/{n_max} fonti — Nessun dato esito"

    p_pm = _clinical_polarity_hint(pubmed_text) if has_pubmed else "unk"
    p_ct = _clinical_polarity_hint(ct_text) if has_ct else "unk"
    fda_b = _fda_outcome_bucket(fda_text) if has_fda else "nd"

    clin = [x for x in (p_pm, p_ct) if x in ("pos", "neg", "mix")]
    clin_set = set(clin)

    def _lbl(z: str) -> str:
        return {"pos": "positivo", "neg": "negativo", "mix": "misto"}.get(z, z)

    reg_note = ""
    if fda_b == "app" and clin_set.intersection({"neg", "mix"}):
        reg_note = (
            " Attenzione: Drugs@FDA segnala approvazione ma un testo clinico "
            "ha marker negativo/misto — verifica manuale."
        )

    if not clin:
        if fda_b == "app":
            return (
                f"{n_have}/{n_max} fonti — Solo regolatorio esplicito (approvazione); "
                f"testi clinici senza marker positivo/negativo chiaro.{reg_note}"
            ).strip()
        return (
            f"{n_have}/{n_max} fonti — Segnale esito non classificabile "
            f"(nessun marker positivo/negativo nei testi disponibili).{reg_note}"
        ).strip()

    if len(clin) == 1:
        return (
            f"{n_have}/{n_max} fonti — Check singola clinica ({_lbl(clin[0])}); "
            f"confronto incrociato limitato.{reg_note}"
        ).strip()

    # Due o più giudizi clinici (PM + CT)
    if "mix" in clin_set:
        return (
            f"{n_have}/{n_max} fonti — Parziale/misto: almeno una fonte con segnale misto "
            f"(positivo+negativo nello stesso testo).{reg_note}"
        ).strip()
    if "pos" in clin_set and "neg" in clin_set:
        parts_d = []
        if has_pubmed and p_pm in ("pos", "neg"):
            parts_d.append(f"PubMed {_lbl(p_pm)}")
        if has_ct and p_ct in ("pos", "neg"):
            parts_d.append(f"CT.gov {_lbl(p_ct)}")
        detail = " vs ".join(parts_d) if parts_d else "fonti cliniche"
        return (
            f"{n_have}/{n_max} fonti — Disaccordo clinico ({detail}).{reg_note}"
        ).strip()
    if clin_set == {"pos"}:
        return (
            f"{n_have}/{n_max} fonti — Concorde (tutte positivo).{reg_note}"
        ).strip()
    if clin_set == {"neg"}:
        return (
            f"{n_have}/{n_max} fonti — Concorde (tutte negativo).{reg_note}"
        ).strip()
    return f"{n_have}/{n_max} fonti — Da rivedere manualmente.{reg_note}".strip()


def _esito_integrato_e_fonti(ct_summ: str, fda_cell: str,
                              pubmed_bundle: dict | None) -> tuple[str, str, str]:
    """Unisce CT.gov, FDA, PubMed; elenco fonti; riga qualità concordanza."""
    pm = pubmed_bundle or {}
    parts: list[str] = []
    src: list[str] = []

    summ = str(pm.get("summary_line") or "").strip()
    hits = pm.get("hits") or []

    def _pubmed_esito_block(d: dict) -> str:
        """Blocca PubMed leggendo dall’abstract (visibile nel testo esito integrato)."""
        h0 = d or {}
        ab = str(h0.get("abstract") or "").strip()
        px = str(h0.get("pmid") or "").strip()
        pn = str(h0.get("pub_year") or "").strip()
        tit = str(h0.get("title") or "").strip()
        if ab:
            cap = 2000
            abx = ab if len(ab) <= cap else (ab[: cap - 1] + "…")
            head = f"PMID {px}" if px else "PubMed"
            if pn:
                head += f" ({pn})"
            suf = f" — {tit}" if tit and len(tit) <= 220 else (f" — {tit[:177]}…" if tit else "")
            blk = head + ": " + abx + suf
            return blk if len(blk) <= 2200 else (blk[:2197] + "…")
        if tit:
            return ((f"PMID {px}: " if px else "") + tit)[:520]
        return ""

    def _pubmed_polarity_blob(h0: dict) -> str:
        """Testo lungo da passare alla polarità (abstract + titolo)."""
        h0 = h0 or {}
        return " ".join(
            x for x in (
                str(h0.get("abstract") or ""),
                str(h0.get("title") or ""),
            ) if x
        ).strip()

    abst_blk = ""
    pm_polarity_src = ""

    pm_ok = bool(summ and summ != "—")
    if isinstance(hits, list) and hits:
        abst_blk = _pubmed_esito_block(hits[0] or {})
        if abst_blk:
            parts.append(abst_blk)
            src.append("PubMed (NCBI)")
            pm_polarity_src = _pubmed_polarity_blob(hits[0] or {})
        elif pm_ok:
            parts.append(summ[:2000])
            src.append("PubMed (NCBI)")
            pm_polarity_src = summ
    elif pm_ok:
        parts.append(summ[:2000])
        src.append("PubMed (NCBI)")
        pm_polarity_src = summ

    ct = str(ct_summ or "").strip()
    ct_has = bool(ct and ct != "—")
    if ct_has:
        parts.append(ct[:380])
        if not any(s.startswith("CT.gov") for s in src):
            src.append("CT.gov (API)")

    ft = str(fda_cell or "").strip()
    fda_has = bool(ft and not ft.startswith("N/D"))
    if fda_has:
        parts.append(ft[:280])
        if not any("FDA" in x for x in src):
            src.append("FDA (OpenFDA)")

    merged = " · ".join(p for p in parts if p)
    if len(merged) > 3200:
        merged = merged[:3197] + "…"
    fonti_s = "; ".join(src) if src else "—"
    qa = _qualita_fonti_esito(
        has_pubmed=bool(any("PubMed" in s for s in src)),
        has_ct=bool(any(s.startswith("CT.gov") for s in src)),
        has_fda=bool(any("FDA" in x for x in src)),
        pubmed_text=pm_polarity_src,
        ct_text=ct if ct_has else "",
        fda_text=ft if fda_has else "",
    )

    merged_out = merged if merged.strip() else "—"
    return merged_out, fonti_s, qa


def _cached_ctgov_esito_bundle_disk_only(nct: str) -> dict:
    """Sintesi CT.gov solo da disco (no HTTP) — usata in `[Pred]` per non forzare fetch."""
    nct_clean = str(nct or "").strip().upper()
    if not nct_clean.startswith("NCT"):
        return _empty_ctgov_bundle()
    safe = "".join(ch for ch in nct_clean if ch.isalnum())
    jpath = os.path.join(_CTGOV_ESITO_CACHE_DIR, f"{safe}.json")
    txt_path = os.path.join(_CTGOV_ESITO_CACHE_DIR, f"{safe}.txt")
    if os.path.isfile(jpath):
        try:
            data = json.loads(
                pathlib.Path(jpath).read_text(encoding="utf-8", errors="replace"))
            if isinstance(data, dict) and "summary" in data:
                return _ctgov_cached_lab_dict(data)
        except Exception:
            pass
    if os.path.isfile(txt_path):
        try:
            _sx = pathlib.Path(txt_path).read_text(
                encoding="utf-8", errors="replace").strip() or "—"
            return dict(_empty_ctgov_bundle(), summary=_sx)
        except Exception:
            pass
    return _empty_ctgov_bundle()


def _prediction_clinical_context(
    row_dict: dict,
    ticker_studies: dict | None,
    comp_date,
    *,
    ct_allow_network: bool,
    pub_allow_network: bool,
) -> tuple[str, str, dict]:
    ts = ticker_studies if ticker_studies is not None else {}
    nct = _nct_lookup_for_completati_row(ts, row_dict)
    if ct_allow_network and nct:
        ct_lab = _cached_ctgov_esito_bundle(nct)
    elif nct:
        ct_lab = _cached_ctgov_esito_bundle_disk_only(nct)
    else:
        ct_lab = _empty_ctgov_bundle()
    ct_summ = str(ct_lab.get("summary") or "—").strip()
    fda_txt = _fda_drugsfda_cell_text(row_dict, ts, nct or "")
    pm_hit: dict = {}
    try:
        from pubmed_eutils_fetch import (
            cached_pubmed_hint_for_completion as _pmod_fp,
        )
    except ImportError:
        _pmod_fp = None

    tk_u = str(row_dict.get("ticker") or "").strip().upper()
    _stu = _completati_study_aligned(ts, tk_u, nct or "", row_dict.get("phase"))
    if _pmod_fp is not None and comp_date is not None:
        try:
            pm_hit = _pmod_fp(
                comp_date,
                phase_str=str(row_dict.get("phase") or ""),
                indication=str((_stu or {}).get("Indicazione") or "")[:220],
                sponsor_or_company=str(row_dict.get("name") or ""),
                drug_token=_fda_intervention_query_token(
                    str((_stu or {}).get("Interventions") or "")),
                allow_network=pub_allow_network,
            )
        except Exception:
            pm_hit = {}
    return ct_summ, fda_txt, (pm_hit or {})


_PRED_DIR_SCALE = ["↓↓ Calo forte", "↓ Calo lieve", "→ Stabile",
                   "↑ Crescita lieve", "↑↑ Forte crescita"]


def _direction_scale_index(direction: str) -> int:
    ds = str(direction or "")
    if ds.startswith("↑↑"):
        return 4
    if ds.startswith("↑"):
        return 3
    if ds.startswith("→"):
        return 2
    if ds.startswith("↓↓"):
        return 0
    if ds.startswith("↓"):
        return 1
    return 2


def _clinical_prediction_overlay(
    direction_adj: str,
    row_dict: dict,
    ticker_studies: dict | None,
    comp_date,
) -> tuple[str, int, str]:
    """
    Modifica direzione e (delta) affidabilità se almeno un contributore OUTCOME ha
    polarità chiara (+/−) su CT o PubMed, oppure bucket FDA «approvazione».

    Nessun cambio se PubMed/CT assenti o solo «non trovato» / testo non classificabile,
    e FDA senza contenuto utile (p.es. solo N/D).
    """
    if not _env_flag_truthy("CLINICAL_PRED_OVERLAY"):
        return direction_adj, 0, ""

    ct_net = _env_flag_truthy("CLINICAL_PRED_CT_FETCH")
    pub_net = _env_flag_truthy("CLINICAL_PRED_PUBMED_NETWORK")

    ct_summ, fda_txt, pm_b = _prediction_clinical_context(
        row_dict, ticker_studies, comp_date,
        ct_allow_network=ct_net, pub_allow_network=pub_net,
    )

    nct_nf = _nct_lookup_for_completati_row(
        ticker_studies if ticker_studies else {}, row_dict)
    ct_nf_lab = (_cached_ctgov_esito_bundle(nct_nf) if ct_net and nct_nf
                 else (_cached_ctgov_esito_bundle_disk_only(nct_nf)
                       if nct_nf else _empty_ctgov_bundle()))
    hits = pm_b.get("hits") if isinstance(pm_b, dict) else None
    summ_pm = str((pm_b or {}).get("summary_line") or "").strip()
    h0 = (hits or [])[0] if isinstance(hits, list) and hits else {}
    pm_blob = ""
    if isinstance(h0, dict):
        pm_blob = " ".join(
            x for x in (str(h0.get("abstract") or ""), str(h0.get("title") or "")) if x
        ).strip()
    if not pm_blob:
        pm_blob = summ_pm

    has_pm = bool(pm_blob and pm_blob != "—")
    has_ct = (
        bool(ct_summ and ct_summ not in ("", "—"))
        and not _ctgov_lab_summary_is_not_found(ct_nf_lab))

    ft = str(fda_txt or "").strip()
    has_fda = bool(ft and not ft.startswith("N/D"))

    p_pm = _clinical_polarity_hint(pm_blob) if has_pm else "unk"
    p_ct = _clinical_polarity_hint(ct_summ) if has_ct else "unk"

    def _pv(z: str) -> int | None:
        return 1 if z == "pos" else (-1 if z == "neg" else None)

    bits: list[tuple[str, int]] = []
    v_pm = _pv(p_pm)
    if v_pm is not None:
        bits.append(("pm", v_pm))
    v_ct = _pv(p_ct)
    if v_ct is not None:
        bits.append(("ct", v_ct))
    fda_b = _fda_outcome_bucket(ft)
    if fda_b == "app":
        bits.append(("fda", 1))

    if len(bits) < 1:
        return direction_adj, 0, ""

    vals = [b[1] for b in bits]
    idx0 = _direction_scale_index(direction_adj)

    if max(vals) > 0 and min(vals) < 0:
        def _toward_center(i: int) -> int:
            if i > 2:
                return i - 1
            if i < 2:
                return i + 1
            return i

        i1 = _toward_center(idx0)
        lab = _PRED_DIR_SCALE[i1]
        note = (
            "Clinical overlay: esiti fonti discordanti (+/−)"
            " → verso zona stabile; aff −5"
        )
        return lab, (-5 if i1 != idx0 else 0), note

    net = sum(vals)
    tgt = 0
    if net >= 2:
        tgt = 1
    elif net <= -2:
        tgt = -1
    elif net == 1:
        tgt = 1
    elif net == -1:
        tgt = -1

    if tgt == 0:
        return direction_adj, 0, ""

    def _toward_tgt(i: int, d_tgt: int) -> tuple[int, int]:
        if d_tgt > 0:
            if i <= 1:
                return min(4, i + 2), 6
            if i == 2:
                return min(4, i + 1), 5
            if i == 3:
                return 4 if i < 4 else i, 3
            return i, 2
        if d_tgt < 0:
            if i >= 3:
                return max(0, i - 2), 6
            if i == 2:
                return max(0, i - 1), 5
            if i == 1:
                return 0 if i > 0 else i, 3
            return i, 2
        return i, 0

    idx1, aff_d = _toward_tgt(idx0, tgt)
    if idx1 == idx0:
        return direction_adj, 0, ""

    polarity = "bull" if tgt > 0 else "bear"
    _nf = len(bits)
    note = (
        f"Clinical overlay: {_nf} fonte/i ({polarity}); "
        f"fine-tune direzione; aff {'+' if aff_d > 0 else ''}{aff_d}"
    )
    return _PRED_DIR_SCALE[idx1], aff_d, note


def _fda_drugsfda_cell_text(row: dict, ticker_studies: dict | None,
                            nct: str) -> str:
    """Testo colonna FDA — solo tier Ph III/IV con logica «6 mesi dopo CD»."""
    from datetime import date as _dac

    tier = _row_phase_tier_max(row.get("phase"))
    if tier not in (3, 4):
        return "N/D (solo Ph III–IV)"

    tk = str(row.get("ticker") or "").strip().upper()
    ts = ticker_studies if ticker_studies is not None else {}
    study = _completati_study_aligned(ts, tk, nct, row.get("phase"))

    dtok = _fda_intervention_query_token(
        (study or {}).get("Interventions", "") or "")
    b = _fda_hint_bundle(dtok, str(row.get("name") or ""))
    ap_iso = b.get("approval_iso")
    if ap_iso:
        try:
            from datetime import datetime as _dtm2
            d = _dtm2.fromisoformat(str(ap_iso)).date()
            return f"Approvazione FDA: {d.strftime('%d/%m/%Y')}"
        except Exception:
            return f"Approvazione FDA: {ap_iso}"

    cd = _normalize_completion_date_ca(row.get("completion_date"))
    if cd and (_dac.today() - cd).days >= _FDA_POST_CD_SILENCE_DAYS:
        return "Nessun record Drugs@FDA rilevante (≥6 m dopo CD)"
    return "In attesa / non in Drugs@FDA (≤6 m)"


def _pcache_path(ticker: str, period: str) -> str:
    safe = ticker.replace("^", "_IDX_").replace("/", "_").replace("\\", "_")
    return os.path.join(_PRICE_CACHE_DIR, f"{safe}_{period}.pkl")


def _price_cache_mode_sticky() -> bool:
    """Default sticky (nessuna riscadenza). Opt-out esplicito per comportamento TTL classico."""
    m = os.environ.get("PRICE_CACHE_MODE", "").strip().lower()
    if m in ("ttl", "default", "normal", "expire"):
        return False
    if m in ("sticky", "persist", "forever", "persistent"):
        return True
    if m != "":
        # Valore PRICE_CACHE_MODE non riconosciuto → TTL (sicuro).
        return False
    sticky_off = os.environ.get("PRICE_CACHE_STICKY", "").strip().lower()
    if sticky_off in ("0", "false", "no", "off"):
        return False
    return True


def _pcache_ttl_hours_effective(period: str) -> float | None:
    """
    Ore massime prima di ignorare il file pickle, oppure None = sticky (sempre valido).
    """
    if _price_cache_mode_sticky():
        return None
    long_p = period in _PRICE_CACHE_LONG_PERIODS
    ek = ("PRICE_CACHE_TTL_LONG_HOURS" if long_p else "PRICE_CACHE_TTL_SHORT_HOURS")
    raw = os.environ.get(ek, "").strip()
    if raw:
        try:
            return max(1.0 / 60.0, float(raw.replace(",", ".")))   # ≥ 1 min
        except ValueError:
            pass
    return (_PRICE_CACHE_TTL_LONG_H if long_p else _PRICE_CACHE_TTL_SHORT_H)


def _pcache_load(ticker: str, period: str):
    """Serie dalla cache se presente e (in modalità TTL) non scaduta; sticky = ignora età."""
    path = _pcache_path(ticker, period)
    if not os.path.exists(path):
        return None
    _ttl_h = _pcache_ttl_hours_effective(period)
    if _ttl_h is not None:
        if (time.time() - os.path.getmtime(path)) / 3600 > _ttl_h:
            return None
    try:
        return pd.read_pickle(path)
    except Exception:
        return None


def _pcache_load_stale(ticker: str, period: str):
    """Come _pcache_load ma ignora il TTL — usato come fallback se il download fallisce."""
    path = _pcache_path(ticker, period)
    if not os.path.exists(path):
        return None
    try:
        return pd.read_pickle(path)
    except Exception:
        return None


def _pcache_save(ticker: str, series: "pd.Series", period: str) -> None:
    os.makedirs(_PRICE_CACHE_DIR, exist_ok=True)
    try:
        series.to_pickle(_pcache_path(ticker, period))
    except Exception:
        pass


def _pcache_path_cv(ticker: str, period: str) -> str:
    """Pickle Close+Volume per periodo (Prediction / Simulation 60d, ecc.)."""
    safe = ticker.replace("^", "_IDX_").replace("/", "_").replace("\\", "_")
    return os.path.join(_PRICE_CACHE_DIR, f"{safe}_{period}_cv.pkl")


def _pcache_load_cv(ticker: str, period: str):
    path = _pcache_path_cv(ticker, period)
    if not os.path.exists(path):
        return None, None
    _ttl_h = _pcache_ttl_hours_effective(period)
    if _ttl_h is not None:
        if (time.time() - os.path.getmtime(path)) / 3600 > _ttl_h:
            return None, None
    try:
        obj = pd.read_pickle(path)
    except Exception:
        return None, None
    if not isinstance(obj, dict):
        return None, None
    c = obj.get("close")
    v = obj.get("volume")
    if c is None or getattr(c, "empty", True):
        return None, None
    if v is None:
        v = pd.Series(dtype=float)
    return c, v


def _pcache_load_cv_stale(ticker: str, period: str):
    path = _pcache_path_cv(ticker, period)
    if not os.path.exists(path):
        return None, None
    try:
        obj = pd.read_pickle(path)
    except Exception:
        return None, None
    if not isinstance(obj, dict):
        return None, None
    c = obj.get("close")
    v = obj.get("volume") or pd.Series(dtype=float)
    if c is None or getattr(c, "empty", True):
        return None, None
    return c, v


def _pcache_save_cv(ticker: str, period: str,
                    close_s: "pd.Series", vol_s: "pd.Series | None") -> None:
    os.makedirs(_PRICE_CACHE_DIR, exist_ok=True)
    try:
        vs = vol_s if vol_s is not None else pd.Series(dtype=float)
        pd.to_pickle({"close": close_s, "volume": vs}, _pcache_path_cv(ticker, period))
    except Exception:
        pass


def _yf_norm_series_tz(ser: "pd.Series") -> "pd.Series":
    if ser is None or getattr(ser, "empty", True):
        return ser
    out = ser.copy()
    try:
        if hasattr(out.index, "tz"):
            out.index = pd.to_datetime(out.index).tz_localize(None)
    except Exception:
        pass
    return out


def _price_tail_merge_disabled() -> bool:
    return os.environ.get("DISABLE_PRICE_TAIL_MERGE", "").strip().lower() in (
        "1", "true", "yes", "on",
    )


def _price_tail_merge_period() -> str:
    p = os.environ.get("PRICE_TAIL_MERGE_PERIOD", "14d").strip()
    return p if p else "14d"


def _yf_parse_close_vol_from_raw(
    raw: "pd.DataFrame", ticker: str, chunk: list[str],
) -> tuple["pd.Series", "pd.Series"]:
    """Estrae Close+Volume da output yfinance.download (singolo/multi ticker).

    yfinance può usare MultiIndex (Field, Ticker) oppure (Ticker, Field); la seconda
    forma richiede ``raw[ticker]['Close']`` come in ``_yf_extract_close_series_from_raw``.
    """
    n = len(chunk)
    if n == 1 and not isinstance(raw.columns, pd.MultiIndex):
        c_raw = raw["Close"] if "Close" in raw.columns else raw.iloc[:, 0]
        v_raw = raw["Volume"] if "Volume" in raw.columns else pd.Series(dtype=float)
        c_s = pd.Series(c_raw, copy=False).astype(float).dropna()
        try:
            v_s = pd.Series(v_raw, copy=False).astype(float).dropna()
        except Exception:
            v_s = pd.Series(dtype=float)
    elif isinstance(raw.columns, pd.MultiIndex):
        lvl0 = raw.columns.get_level_values(0)
        if "Close" in lvl0:
            c_s = raw["Close"].get(ticker, pd.Series()).dropna().astype(float)
            v_s = (raw["Volume"].get(ticker, pd.Series()).dropna().astype(float)
                   if "Volume" in lvl0 else pd.Series(dtype=float))
        else:
            # Livello 0 = ticker (come ``_yf_extract_close_series_from_raw``)
            sub = raw[ticker]
            if isinstance(sub, pd.DataFrame):
                c_s = sub.get("Close", pd.Series(dtype=float))
                c_s = pd.Series(c_s, copy=False).dropna().astype(float)
                v_col = sub.get("Volume", pd.Series(dtype=float))
                try:
                    v_s = pd.Series(v_col, copy=False).dropna().astype(float)
                except Exception:
                    v_s = pd.Series(dtype=float)
            else:
                c_s = pd.Series(sub, copy=False).dropna().astype(float)
                v_s = pd.Series(dtype=float)
    else:
        raise ValueError("unsupported raw frame")
    return _yf_norm_series_tz(c_s), _yf_norm_series_tz(v_s)


def _yf_extract_close_series_from_raw(
    raw: "pd.DataFrame", ticker: str, chunk: list[str],
) -> "pd.Series":
    n = len(chunk)
    if n == 1:
        s = (raw["Close"] if "Close" in raw.columns else raw.iloc[:, 0]).dropna()
    elif isinstance(raw.columns, pd.MultiIndex):
        lvl0 = raw.columns.get_level_values(0)
        if "Close" in lvl0:
            s = raw["Close"].get(ticker, pd.Series()).dropna()
        else:
            s = raw[ticker].get("Close", pd.Series()).dropna()
    else:
        s = raw[ticker].dropna() if ticker in raw.columns else pd.Series()
    return _yf_norm_series_tz(s.astype(float))


def _yf_combine_price_series(
    old: "pd.Series | None",
    tail: "pd.Series | None",
    *,
    trim_calendar_days: int | None,
) -> "pd.Series":
    """Unisce serie storiche + finestrella recente; sulle date comuni vince ``tail``."""
    old_x = old if old is not None else pd.Series(dtype=float)
    tail_x = tail if tail is not None else pd.Series(dtype=float)
    # pandas 3.x: copy= in astype è deprecato (Copy-on-Write gestisce le copie).
    old_x = _yf_norm_series_tz(old_x).astype(float)
    tail_x = _yf_norm_series_tz(tail_x).astype(float)
    if tail_x.empty:
        out = old_x
    elif old_x.empty:
        out = tail_x
    else:
        try:
            out = pd.concat([old_x, tail_x]).sort_index()
            out = out[~out.index.duplicated(keep="last")]
        except Exception:
            out = old_x

    if (trim_calendar_days is not None and out is not None
            and not getattr(out, "empty", True)):
        try:
            mx = pd.Timestamp(pd.Timestamp(out.index.max()).normalize())
            floor_dt = mx - pd.Timedelta(days=int(trim_calendar_days))
            out = out[out.index.map(
                lambda ix: pd.Timestamp(ix).normalize() >= floor_dt
            )]
        except Exception:
            pass

    try:
        return out.astype(float) if out is not None else pd.Series(dtype=float)
    except Exception:
        return out


def _yf_tail_merge_into_close_vol_dicts(
    closes: dict,
    volumes: dict,
    all_syms: list[str],
    yf_mod,
    *,
    persist_period: str,
    trim_calendar_days: int | None,
) -> None:
    """Scarica ``PRICE_TAIL_MERGE_PERIOD`` (default ~14d) e aggiorna cache Close+Vol."""
    if _price_tail_merge_disabled() or not all_syms:
        return

    merged_any = False
    mini_p = _price_tail_merge_period()
    _CHUNK = 50
    to_refresh = [
        tk for tk in all_syms
        if tk in closes and closes[tk] is not None and not closes[tk].empty]
    if not to_refresh:
        return

    for ci_start in range(0, len(to_refresh), _CHUNK):
        chunk = to_refresh[ci_start: ci_start + _CHUNK]
        try:
            raw = yf_mod.download(
                chunk if len(chunk) > 1 else chunk[0],
                period=mini_p,
                auto_adjust=True,
                group_by="ticker",
                progress=False,
            )
        except Exception:
            continue
        if raw is None or getattr(raw, "empty", True):
            continue

        for tk in chunk:
            if tk not in closes:
                continue
            try:
                c_mini, v_mini = _yf_parse_close_vol_from_raw(raw, tk, chunk)
            except Exception:
                continue

            nc = _yf_combine_price_series(
                closes[tk], c_mini, trim_calendar_days=trim_calendar_days)
            nv = volumes.get(tk)
            if nv is not None and not getattr(nv, "empty", False):
                nv = _yf_combine_price_series(nv, v_mini,
                                              trim_calendar_days=trim_calendar_days)
            elif not v_mini.empty:
                nv = v_mini.copy()
            else:
                nv = pd.Series(dtype=float)

            closes[tk] = nc
            volumes[tk] = nv
            _pcache_save_cv(tk, persist_period, nc, nv)
            merged_any = True

    if merged_any:
        print(f"[PriceCache] Tail-merge `{mini_p}` applicato ({persist_period}_cv.pkl): "
              f"dati giornalieri aggiornati, storico preservato dalla cache.", flush=True)


def _yf_tail_merge_into_close_only_dict(
    closes: dict,
    all_syms: list[str],
    yf_mod,
    *,
    persist_period: str,
    trim_calendar_days: int | None,
) -> None:
    """Come sopra solo Close (serie ``period``.pkl)."""
    if _price_tail_merge_disabled() or not all_syms:
        return

    merged_any = False
    mini_p = _price_tail_merge_period()
    _CHUNK = 50
    to_refresh = [
        tk for tk in all_syms
        if tk in closes and closes[tk] is not None and not closes[tk].empty]
    if not to_refresh:
        return

    for ci_start in range(0, len(to_refresh), _CHUNK):
        chunk = to_refresh[ci_start: ci_start + _CHUNK]
        try:
            raw = yf_mod.download(
                chunk if len(chunk) > 1 else chunk[0],
                period=mini_p,
                auto_adjust=True,
                group_by="ticker",
                progress=False,
            )
        except Exception:
            continue
        if raw is None or getattr(raw, "empty", True):
            continue

        for tk in chunk:
            if tk not in closes:
                continue
            try:
                c_mini = _yf_extract_close_series_from_raw(raw, tk, chunk)
            except Exception:
                continue
            if c_mini.empty:
                continue

            nc = _yf_combine_price_series(
                closes[tk], c_mini, trim_calendar_days=trim_calendar_days)
            closes[tk] = nc
            _pcache_save(tk, nc, persist_period)
            merged_any = True

    if merged_any:
        print(f"[PriceCache] Tail-merge `{mini_p}` applicato ({persist_period}.pkl): "
              f"ultime barre aggiornate.", flush=True)


def _yf_batch_close_vol(
    tickers: list,
    period: str,
    yf_mod,
    *,
    merge_recent_tail: bool = False,
    tail_trim_calendar_days: int | None = None,
) -> tuple[dict, dict]:
    """
    Close + Volume per più ticker con cache su disco (``*_period_cv.pkl``).
    Stessa politica TTL/sticky dei file Close-only.

    Con ``merge_recent_tail=True`` dopo il caricamento pieno unisce anche
    ``PRICE_TAIL_MERGE_PERIOD`` (~ultime sedute da Yahoo); il grosso storico resta nei .pkl.
    """
    global _PRICE_CACHE_FIRST_RUN_LOGGED
    if not _PRICE_CACHE_FIRST_RUN_LOGGED:
        _PRICE_CACHE_FIRST_RUN_LOGGED = True
        if _price_cache_mode_sticky():
            print("[PriceCache] Modalità sticky (default): .pkl senza scadenza automatica "
                  "| TTL classico: PRICE_CACHE_MODE=ttl o PRICE_CACHE_STICKY=0")
        else:
            print("[PriceCache] Modalità TTL: periodi lunghi "
                  f"{_PRICE_CACHE_TTL_LONG_H}h, brevi {_PRICE_CACHE_TTL_SHORT_H}h "
                  "(override PRICE_CACHE_TTL_*_HOURS)")

    closes_r: dict = {}
    vols_r: dict = {}
    to_dl: list = []
    for tk in tickers:
        c0, v0 = _pcache_load_cv(tk, period)
        if c0 is not None and not c0.empty:
            closes_r[tk] = c0
            vols_r[tk] = (v0 if v0 is not None and not getattr(v0, "empty", True)
                          else pd.Series(dtype=float))
        else:
            to_dl.append(tk)

    _CHUNK = 50
    still_missing: list = []
    if to_dl:
        n_chunks = (len(to_dl) + _CHUNK - 1) // _CHUNK
        for ci, ci_start in enumerate(range(0, len(to_dl), _CHUNK)):
            chunk = to_dl[ci_start: ci_start + _CHUNK]
            print(f"  [PriceCache+Vol] Download {ci+1}/{n_chunks}: {len(chunk)} ticker "
                  f"(period={period}) …", end=" ", flush=True)
            ok = 0
            try:
                raw = yf_mod.download(
                    chunk if len(chunk) > 1 else chunk[0],
                    period=period, auto_adjust=True, group_by="ticker", progress=False,
                )
                if raw is None or getattr(raw, "empty", True):
                    still_missing.extend(chunk)
                    print("vuoto")
                    continue

                for tk in chunk:
                    try:
                        c_s, v_s = _yf_parse_close_vol_from_raw(raw, tk, chunk)
                        if c_s.empty:
                            still_missing.append(tk)
                            continue
                        _pcache_save_cv(tk, period, c_s, v_s)
                        closes_r[tk] = c_s
                        vols_r[tk] = v_s if not v_s.empty else pd.Series(dtype=float)
                        ok += 1
                    except Exception:
                        still_missing.append(tk)
                print(f"OK ({ok}/{len(chunk)})")
            except Exception as _cve:
                print(f"errore: {_cve}")
                still_missing.extend(chunk)

    if still_missing:
        stale_k = 0
        for tk in still_missing:
            if tk in closes_r:
                continue
            c1, v1 = _pcache_load_cv_stale(tk, period)
            if c1 is not None and not c1.empty:
                closes_r[tk] = c1
                vols_r[tk] = (v1 if v1 is not None and not getattr(v1, "empty", True)
                              else pd.Series(dtype=float))
                stale_k += 1
        if stale_k:
            print(f"  [PriceCache+Vol] Fallback stale: {stale_k} ticker recuperati.")

    if merge_recent_tail and closes_r:
        _yf_tail_merge_into_close_vol_dicts(
            closes_r,
            vols_r,
            list(tickers),
            yf_mod,
            persist_period=period,
            trim_calendar_days=tail_trim_calendar_days,
        )

    return closes_r, vols_r


def _yf_batch_close(
    tickers: list,
    period: str,
    yf_mod,
    *,
    merge_recent_tail: bool = False,
    tail_trim_calendar_days: int | None = None,
) -> dict:
    """
    Scarica la serie Close per ogni ticker, usando la cache su disco.
    Ritorna dict {ticker: pd.Series}.  Solo i ticker non in cache vengono
    scaricati da yfinance (batch download, chunk da 50).

    Fallback stale: se il download fallisce (rate-limit), usa la cache
    scaduta piuttosto che restituire dati vuoti.

    ``merge_recent_tail``: dopo cache/download pieno, scarica ``PRICE_TAIL_MERGE_PERIOD``
    (≈ ultime sedute) e fonde sulla serie poi riscrive il pickle — mantiene lo storico
    in locale e aggiorna le barre “di oggi”. Disattiva con ``DISABLE_PRICE_TAIL_MERGE=1``.
    """
    global _PRICE_CACHE_FIRST_RUN_LOGGED
    if not _PRICE_CACHE_FIRST_RUN_LOGGED:
        _PRICE_CACHE_FIRST_RUN_LOGGED = True
        if _price_cache_mode_sticky():
            print("[PriceCache] Modalità sticky (default): .pkl senza scadenza automatica "
                  "| TTL classico: PRICE_CACHE_MODE=ttl o PRICE_CACHE_STICKY=0")
        else:
            print("[PriceCache] Modalità TTL: periodi lunghi "
                  f"{_PRICE_CACHE_TTL_LONG_H}h, brevi {_PRICE_CACHE_TTL_SHORT_H}h "
                  "(override PRICE_CACHE_TTL_*_HOURS)")
    result: dict = {}
    to_download: list = []

    # Carica dalla cache (sticky o entro TTL)
    for tk in tickers:
        cached = _pcache_load(tk, period)
        if cached is not None and not cached.empty:
            result[tk] = cached
        else:
            to_download.append(tk)

    _CHUNK = 50
    still_missing: list = []
    if to_download:
        n_chunks = (len(to_download) + _CHUNK - 1) // _CHUNK
        for ci, ci_start in enumerate(range(0, len(to_download), _CHUNK)):
            chunk = to_download[ci_start: ci_start + _CHUNK]
            print(f"  [PriceCache] Download {ci+1}/{n_chunks}: {len(chunk)} ticker "
                  f"(period={period}) …", end=" ", flush=True)
            try:
                raw = yf_mod.download(chunk, period=period, auto_adjust=True,
                                      group_by="ticker", progress=False)
                ok = 0
                failed_in_chunk: list = []
                for tk in chunk:
                    try:
                        n = len(chunk)
                        if n == 1:
                            s = (raw["Close"] if "Close" in raw.columns
                                 else raw.iloc[:, 0]).dropna()
                        elif isinstance(raw.columns, pd.MultiIndex):
                            lvl0 = raw.columns.get_level_values(0)
                            if "Close" in lvl0:
                                s = raw["Close"].get(tk, pd.Series()).dropna()
                            else:
                                s = raw[tk].get("Close", pd.Series()).dropna()
                        else:
                            s = raw[tk].dropna() if tk in raw.columns else pd.Series()
                        if s.empty:
                            failed_in_chunk.append(tk)
                            continue
                        if hasattr(s.index, "tz"):
                            s.index = pd.to_datetime(s.index).tz_localize(None)
                        result[tk] = s
                        _pcache_save(tk, s, period)
                        ok += 1
                    except Exception:
                        failed_in_chunk.append(tk)
                print(f"OK ({ok}/{len(chunk)})")
                still_missing.extend(failed_in_chunk)
            except Exception as _de:
                print(f"errore: {_de}")
                still_missing.extend(chunk)

    # ── Fallback stale: per ticker non scaricati usa cache scaduta ────────────
    if still_missing:
        stale_ok = 0
        for tk in still_missing:
            stale = _pcache_load_stale(tk, period)
            if stale is not None and not stale.empty:
                result[tk] = stale
                stale_ok += 1
        if stale_ok:
            print(f"  [PriceCache] Fallback stale: {stale_ok}/{len(still_missing)} "
                  f"ticker recuperati da cache scaduta (rate-limit yfinance).")
        missing_final = [tk for tk in still_missing if tk not in result]
        if missing_final:
            print(f"  [PriceCache] {len(missing_final)} ticker senza dati "
                  f"(nessuna cache disponibile): {missing_final}")

    if merge_recent_tail and result:
        _yf_tail_merge_into_close_only_dict(
            result,
            list(tickers),
            yf_mod,
            persist_period=period,
            trim_calendar_days=tail_trim_calendar_days,
        )

    return result


def _histlib_safe_sym(ticker: str) -> str:
    return (ticker or "").replace("^", "_IDX_").replace("/", "_").replace("\\", "_")


def _histlib_cv_pickle_path(ticker: str) -> str:
    return os.path.join(_PRICE_CACHE_DIR, f"{_histlib_safe_sym(ticker)}_{_HISTLIB_CV_TAG}.pkl")


def _histlib_force_cv_redownload() -> bool:
    return os.environ.get("FORCE_HISTLIB_CV_DOWNLOAD", "").strip() in ("1", "true", "TRUE", "yes")


def _histlib_load_cv_pair(ticker: str) -> dict | None:
    path = _histlib_cv_pickle_path(ticker)
    if not os.path.exists(path):
        return None
    try:
        obj = pd.read_pickle(path)
        if not isinstance(obj, dict):
            return None
        c = obj.get("close")
        v = obj.get("volume")
        if c is None or getattr(c, "empty", True):
            return None
        return {"close": c, "volume": v}
    except Exception:
        return None


def _histlib_save_cv_pair(ticker: str, close_s: "pd.Series", volume_s: "pd.Series | None") -> None:
    os.makedirs(_PRICE_CACHE_DIR, exist_ok=True)
    try:
        pd.to_pickle(
            {"close": close_s, "volume": volume_s},
            _histlib_cv_pickle_path(ticker),
        )
    except Exception:
        pass


def _histlib_normalize_ts_index(series: "pd.Series") -> "pd.Series":
    """Indice temporale naive (DatetimeIndex ordinato per slice ≤ data)."""
    if series is None:
        return series
    # Non usare getattr(..., "empty", True): numpy.ndarray non ha .empty e verrebbe
    # trattato come vuoto → ritorno inalterato con valori (n,1) e crash a valle.
    try:
        if hasattr(series, "empty") and bool(series.empty):
            return series
    except TypeError:
        pass
    try:
        # Cache pickle / df slice possono essere DataFrame 1 col → Series 1D
        # (pd.Series(ndarray shaped (n,1)) → "Data must be 1-dimensional").
        _s_raw = series
        if isinstance(_s_raw, pd.DataFrame):
            if _s_raw.shape[1] == 1:
                _s_raw = _s_raw.iloc[:, 0]
            else:
                return pd.Series(dtype=float)
        s = _s_raw.astype(float).copy()
        import numpy as _np_hw
        _vals = _np_hw.asarray(s.values, dtype=float)
        if _vals.ndim > 1:
            _vals = _np_hw.squeeze(_vals)
        if _vals.ndim != 1:
            _vals = _np_hw.ravel(_vals)
        idx = pd.DatetimeIndex(pd.to_datetime(s.index, errors="coerce"))
        if getattr(idx, "tz", None) is not None:
            idx = idx.tz_convert("UTC").tz_localize(None)
        idx = idx.normalize()
        mask = ~(pd.isna(idx))
        if not mask.any():
            return pd.Series(dtype=float)
        return pd.Series(_np_hw.ravel(_vals[mask]), index=idx[mask]).sort_index()
    except Exception:
        try:
            if isinstance(series, pd.DataFrame) and series.shape[1] == 1:
                series = series.iloc[:, 0]
            return series.astype(float)
        except Exception:
            return series


def _hist_close_at_session_offset(close_series: "pd.Series", cd_ts, off: int) -> float | None:
    """
    Chiusura alla sessione richiesta rispetto al completion date — **stessa semantica**
    di ``_compute_past_catalyst_data._close_at_off``: ``off < 0`` = |off| **sessioni di borsa**
    prima del timestamp CD (serie filtrata ``index < cd``); ``off > 0`` = dopo CD.
    """
    if close_series is None or getattr(close_series, "empty", True):
        return None
    s = close_series.dropna()
    if s.empty:
        return None
    tscd = pd.Timestamp(cd_ts)
    if off < 0:
        pre = s[s.index < tscd]
        if len(pre) < abs(off):
            return None
        try:
            return round(float(pre.iloc[off]), 2)
        except Exception:
            return None
    if off > 0:
        post = s[s.index > tscd]
        if len(post) < off:
            return None
        try:
            return round(float(post.iloc[off - 1]), 2)
        except Exception:
            return None
    cdp = s[s.index >= tscd]
    if cdp.empty:
        return None
    try:
        return round(float(cdp.iloc[0]), 2)
    except Exception:
        return None


def _hist_trade_date_at_session_offset(close_series: "pd.Series", cd_ts, off: int):
    """
    Data di calendario della barra usata da ``_hist_close_at_session_offset`` per lo stesso
    ``cd_ts`` e ``off`` (sessioni di borsa pre/post CD).
    """
    if close_series is None or getattr(close_series, "empty", True):
        return None
    s = close_series.dropna()
    if s.empty:
        return None
    tscd = pd.Timestamp(cd_ts)
    if off < 0:
        pre = s[s.index < tscd]
        if len(pre) < abs(off):
            return None
        try:
            lab = pre.index[off]
            return pd.Timestamp(lab).normalize().date()
        except Exception:
            return None
    if off > 0:
        post = s[s.index > tscd]
        if len(post) < off:
            return None
        try:
            lab = post.index[off - 1]
            return pd.Timestamp(lab).normalize().date()
        except Exception:
            return None
    cdp = s[s.index >= tscd]
    if cdp.empty:
        return None
    try:
        lab = cdp.index[0]
        return pd.Timestamp(lab).normalize().date()
    except Exception:
        return None


def _nearest_hist_trade_date_to_calendar(
    close_series: "pd.Series | None",
    cal_target: date,
    *,
    max_snap_days: int = 7,
) -> date | None:
    """
    Se esiste una barra esattamente in ``cal_target``, la restituisce.

    Altrimenti considera solo la sessione **immediatamente precedente** e quella **successiva**
    nella serie (come ``bisect`` sui giorni con barra). La sessione scelta è quella con distanza
    minima in giorni di calendario; a parità preferisce la data **più bassa** (precedente).

    Se entrambe le candidate distano più di ``max_snap_days`` da ``cal_target`` (tipico: target
    oltre fine serie o prima IPO), restituisce ``None`` così il chiamante può mostrare il solo
    giorno **CD±N** senza collassare più colonne sulla stessa seduta.
    """
    import bisect

    if close_series is None or getattr(close_series, "empty", True):
        return None
    s = close_series.dropna()
    if s.empty:
        return None
    _uniq: list[date] = []
    _seen: set[date] = set()
    for _ix in s.index:
        try:
            _d = pd.Timestamp(_ix).normalize().date()
        except Exception:
            continue
        if not isinstance(_d, date) or _d in _seen:
            continue
        _seen.add(_d)
        _uniq.append(_d)
    if not _uniq:
        return None
    _uniq.sort()
    if cal_target in _seen:
        return cal_target
    _i = bisect.bisect_left(_uniq, cal_target)
    _cand: list[date] = []
    if _i > 0:
        _cand.append(_uniq[_i - 1])
    if _i < len(_uniq):
        _cand.append(_uniq[_i])
    if not _cand:
        return None
    _best = min(_cand, key=lambda dd: (abs((dd - cal_target).days), dd))
    if abs((_best - cal_target).days) <= int(max_snap_days):
        return _best
    return None


def _histlib_close_on_trade_date(
    close_series: "pd.Series | None",
    trade_d: date,
) -> float | None:
    """
    Chiusura sulla barra il cui giorno di calendario coincide con ``trade_d`` (match sull’indice
    della serie HistLib normalizzata).
    """
    if close_series is None or getattr(close_series, "empty", True) or trade_d is None:
        return None
    s = close_series.dropna()
    if s.empty:
        return None
    for _ix, _v in s.items():
        try:
            _id = pd.Timestamp(_ix).normalize().date()
        except Exception:
            continue
        if _id != trade_d:
            continue
        try:
            _x = float(_v)
        except (TypeError, ValueError):
            return None
        if _x > 0:
            return round(_x, 2)
    return None


def _histlib_unique_sorted_trade_dates(close_series: "pd.Series | None") -> list:
    """Giorni di negoziazione (date) unici ordinati nella serie Close HistLib."""
    if close_series is None or getattr(close_series, "empty", True):
        return []
    s = close_series.dropna()
    if s.empty:
        return []
    _seen: set = set()
    out: list = []
    for _ix in s.index:
        try:
            _d = pd.Timestamp(_ix).normalize().date()
        except Exception:
            continue
        if _d not in _seen:
            _seen.add(_d)
            out.append(_d)
    out.sort()
    return out


def _histlib_prev_trade_date_strictly_before(
    close_series: "pd.Series | None",
    session_day,
) -> date | None:
    """
    Ultima seduta con barra **strettamente precedente** a ``session_day`` (stesso calendario
    della serie — es. NASDAQ). Se ``session_day`` è una seduta in serie, si usa la barra
    immediatamente precedente nell’indice temporale.
    """
    if close_series is None or session_day is None:
        return None
    if not isinstance(session_day, date):
        return None
    u = _histlib_unique_sorted_trade_dates(close_series)
    if not u:
        return None
    import bisect

    if session_day in u:
        k = u.index(session_day)
        return u[k - 1] if k > 0 else None
    k = bisect.bisect_left(u, session_day)
    return u[k - 1] if k > 0 else None


def _histlib_accuracy_sim_resolve_close_series(
    tk: str, ser_cache: dict,
) -> "pd.Series | None":
    """
    Serie Close HistLib per «Accuratezza Simulation»: ``ser_cache`` mutabile per ticker;
    warrant senza pickle/serie → prova il common (…W → …).
    """
    tk = str(tk or "").strip().upper()
    if not tk:
        return None
    if tk not in ser_cache:
        pack = _histlib_load_cv_pair(tk)
        ser = None
        if isinstance(pack, dict) and pack.get("close") is not None:
            hn = _histlib_normalize_ts_index(pack["close"])
            if hn is not None and not getattr(hn, "empty", True):
                ser = hn
        ser_cache[tk] = ser
    cls = ser_cache.get(tk)
    if cls is None and len(tk) >= 2 and tk.endswith("W"):
        alt0 = tk[:-1]
        if alt0 and alt0 not in ser_cache:
            pack0 = _histlib_load_cv_pair(alt0)
            ser0 = None
            if isinstance(pack0, dict) and pack0.get("close") is not None:
                hn0 = _histlib_normalize_ts_index(pack0["close"])
                if hn0 is not None and not getattr(hn0, "empty", True):
                    ser0 = hn0
            ser_cache[alt0] = ser0
        cls = ser_cache.get(alt0)
    return cls


def _acc_sim_histlib_has_session_closes(dd: dict | None) -> bool:
    """True se il record ha almeno una chiusura sessione (JSON/backfill)."""
    if not isinstance(dd, dict):
        return False
    for _pk in (
        "close_m60",
        "close_m60_cal",
        "close_m30",
        "close_m30_cal",
        "close_m10",
        "close_m10_cal",
        "close_m7",
        "close_m5",
        "close_m3",
        "close_p3",
        "close_p4",
        "close_p5",
        "close_p7",
    ):
        try:
            if float(dd.get(_pk)) > 0:
                return True
        except (TypeError, ValueError):
            continue
    return False


def _accuracy_sim_histlib_backfill_session_closes(filtered_rows: dict) -> int:
    """
    Se mancano chiusure nel record ma HistLib ha la serie, valorizza ``close_m*`` / ``close_p*``.

    Per ogni cella: si fissa prima l’**ancora di sessione** rispetto al CD della riga
    (stessa semantica di ``_hist_close_at_session_offset`` / PastCatalyst: pre‑CD = barre con
    ``index < CD``, poi la N‑esima sessione prima dell’ultima pre‑CD; post‑CD = N sessioni dopo
    il CD). Solo dopo si legge la **chiusura** su quella barra dalla serie HistLib.
    """
    if not filtered_rows:
        return 0
    if os.environ.get("PASTCATALYST_DISABLE_HISTLIB", "").strip().lower() in (
            "1", "true", "yes", "on"):
        return 0
    _specs = (
        (-60, "close_m60", ("close_m60", "close_m60_cal")),
        (-30, "close_m30", ("close_m30", "close_m30_cal")),
        (-10, "close_m10", ("close_m10", "close_m10_cal")),
        (-7, "close_m7", ("close_m7",)),
        (-5, "close_m5", ("close_m5",)),
        (-3, "close_m3", ("close_m3",)),
        (3, "close_p3", ("close_p3",)),
        (4, "close_p4", ("close_p4",)),
        (5, "close_p5", ("close_p5",)),
        (7, "close_p7", ("close_p7",)),
    )

    def _slot_has_close(rr: dict, keys: tuple[str, ...]) -> bool:
        for _ky in keys:
            v = rr.get(_ky)
            if v is None:
                continue
            try:
                if float(v) > 0:
                    return True
            except (TypeError, ValueError):
                continue
        return False

    nupd = 0
    ser_cache: dict = {}
    for _rk, row in filtered_rows.items():
        if not isinstance(row, dict):
            continue
        tk = str(row.get("ticker") or (_rk.partition("|")[0] if "|" in str(_rk) else "")).strip().upper()
        if not tk:
            continue
        cd = _normalize_completion_date_ca(row.get("completion_date"))
        if cd is None:
            continue
        cls = _histlib_accuracy_sim_resolve_close_series(tk, ser_cache)
        if cls is None:
            continue
        for _off, _pk, _check in _specs:
            if _slot_has_close(row, _check):
                continue
            val = _hist_close_at_session_offset(cls, cd, _off)
            # Warrant (…W): spesso <60 sessioni quotate prima del CD; prova il common (es. ENGNW→ENGN).
            if (
                val is None
                and _off < 0
                and len(tk) >= 2
                and tk.endswith("W")
            ):
                alt_tk = tk[:-1]
                if alt_tk:
                    cls_alt = _histlib_accuracy_sim_resolve_close_series(alt_tk, ser_cache)
                    if cls_alt is not None:
                        val = _hist_close_at_session_offset(cls_alt, cd, _off)
            if val is not None and val > 0:
                row[_pk] = val
                nupd += 1
    return nupd


def _accuracy_sim_enrich_curve_records(
    filtered_rows: dict,
    *,
    sim_pred_data: dict | None = None,
    refresh_histlib: bool = False,
    log_label: str = "Accuracy",
    fast_skip_existing_seq: bool = False,
    financial_df=None,
    today=None,
) -> tuple[int, int]:
    """
    Arricchisce in-place i record ``TICKER|CD`` con:

    - chiusure **calendario** (``close_m60_cal``, ``close_m30_cal``, …) da HistLib;
    - ``seq_curve_*`` (ricalibrazione sequenziale) se assenti o se non ``fast_skip``.

    Ritorna ``(n_celle_close_cal, n_curve_seq)``.
    """
    if not filtered_rows:
        return 0, 0
    from datetime import date as _date_cls

    if today is None:
        _today = _date_cls.today()
    elif hasattr(today, "date"):
        _today = today.date()
    else:
        _today = today

    if refresh_histlib and _histlib_refresh_on_enrich_enabled():
        _seen_tk: set[str] = set()
        _tk_list: list[str] = []
        for _rk, _row in filtered_rows.items():
            if not isinstance(_row, dict):
                continue
            _tk = str(
                _row.get("ticker")
                or (_rk.partition("|")[0] if "|" in str(_rk) else "")
            ).strip().upper()
            if _tk and _tk not in _seen_tk:
                _seen_tk.add(_tk)
                _tk_list.append(_tk)
        if _tk_list:
            _grafici_refresh_histlib_from_yfinance(
                _tk_list, force=False, min_lag_days=_histlib_min_lag_days()
            )

    _cal_specs = (
        (-60, "close_m60_cal"),
        (-30, "close_m30_cal"),
        (-10, "close_m10_cal"),
        (-4, "close_m4"),
        (4, "close_p4"),
    )

    def _slot_has_close(rr: dict, keys: tuple[str, ...]) -> bool:
        for _ky in keys:
            v = rr.get(_ky)
            if v is None:
                continue
            try:
                if float(v) > 0:
                    return True
            except (TypeError, ValueError):
                continue
        return False

    def _seq_curve_populated(rr: dict) -> bool:
        _sq = rr.get("seq_curve_pct_vs_m60")
        if not isinstance(_sq, (list, tuple)):
            return False
        if len(_sq) < len(SIMULATION_PRED_CAL_OFFSETS):
            return False
        return any(
            _x is not None and _x == _x for _x in _sq[: len(SIMULATION_PRED_CAL_OFFSETS)]
        )

    n_cal = 0
    n_seq = 0
    ser_cache: dict = {}
    _k8_sub_cache: dict = {}
    _keys = list(filtered_rows.keys())
    _n_rows = len(_keys)
    _label = str(log_label or "Accuracy").strip() or "Accuracy"
    if _n_rows >= 100:
        print(f"[{_label}] Enrich curve: 0/{_n_rows} …", flush=True)

    for _i, _rk in enumerate(_keys):
        row = filtered_rows.get(_rk)
        if not isinstance(row, dict):
            continue
        if _i > 0 and _i % 100 == 0:
            print(f"[{_label}] Enrich curve: {_i}/{_n_rows} …", flush=True)

        _tk = str(
            row.get("ticker") or (_rk.partition("|")[0] if "|" in str(_rk) else "")
        ).strip().upper()
        if not _tk:
            continue
        cd = _normalize_completion_date_ca(row.get("completion_date"))
        if cd is None and "|" in str(_rk):
            try:
                cd = _date_cls.fromisoformat(str(_rk).split("|", 1)[1].strip()[:10])
            except Exception:
                cd = None
        if cd is None:
            continue

        if sim_pred_data:
            _sn7_cd7_overlay_seq_curve_from_live(
                row,
                row_key=str(_rk),
                ticker_upper=_tk,
                sim_pred_data=sim_pred_data,
            )

        _ser = _histlib_accuracy_sim_resolve_close_series(_tk, ser_cache)
        if _ser is not None and not getattr(_ser, "empty", True):
            for _off, _pk in _cal_specs:
                if _slot_has_close(row, (_pk,)):
                    continue
                val = _pred_curve_close_cal(_ser, cd, int(_off))
                if (
                    val is None
                    and int(_off) < 0
                    and len(_tk) >= 2
                    and _tk.endswith("W")
                ):
                    _alt = _tk[:-1]
                    if _alt:
                        _ser_alt = _histlib_accuracy_sim_resolve_close_series(
                            _alt, ser_cache
                        )
                        if _ser_alt is not None:
                            val = _pred_curve_close_cal(_ser_alt, cd, int(_off))
                if val is not None and float(val) > 0:
                    row[_pk] = round(float(val), 6)
                    n_cal += 1

        if fast_skip_existing_seq and _seq_curve_populated(row):
            continue

        _had_seq = _seq_curve_populated(row)
        _grafici_ensure_seq_curve_on_pairwise(
            row,
            cd,
            row_key=str(_rk),
            today=_today,
            ser_cache=ser_cache,
            financial_df=financial_df,
            sub_cache=_k8_sub_cache,
        )
        if not _had_seq and _seq_curve_populated(row):
            n_seq += 1

    return n_cal, n_seq


def _yf_batch_histlib_close_volume(
    tickers: list,
    yf_mod,
    period: str | None = None,
) -> dict[str, dict]:
    """
    Close + Volume storici lunghi — cache pickle dedicata, senza TTL.
    Ritorna { ticker: {'close': Series, 'volume': Series|None } }.

    FORCE_HISTLIB_CV_DOWNLOAD=1 forza nuovo scarico anche se pickle esiste.

    ``period``: default da ``HISTLIB_YF_PERIOD`` (tipicamente 10y — evita ``max``
    quando yfinance risponde «Period invalid» su ^XBI).
    """
    if period is None:
        period = _histlib_yfinance_period()
    out: dict[str, dict] = {}
    need: list = []
    force = _histlib_force_cv_redownload()
    for tk in tickers:
        if not tk or not str(tk).strip():
            continue
        tk = str(tk).strip().upper()
        if force:
            try:
                p = _histlib_cv_pickle_path(tk)
                if os.path.exists(p):
                    os.remove(p)
            except Exception:
                pass
        cached = None if force else _histlib_load_cv_pair(tk)
        if cached is not None:
            out[tk] = {
                "close": _histlib_normalize_ts_index(cached["close"]),
                "volume": _histlib_normalize_ts_index(cached["volume"])
                          if cached.get("volume") is not None else None,
            }
        else:
            need.append(tk)

    if not need:
        return out

    _CHUNK = 40
    for ci, ci_start in enumerate(range(0, len(need), _CHUNK)):
        chunk = need[ci_start: ci_start + _CHUNK]
        print(f"  [HistLib] Download storico [{ci_start+1}-{ci_start+len(chunk)}/{len(need)}] "
              f"period={period} …", flush=True)
        try:
            raw = yf_mod.download(
                chunk, period=period, auto_adjust=True,
                group_by="ticker", progress=False,
            )
        except Exception as _he:
            print(f"  [HistLib] batch errore: {_he}")
            continue

        n = len(chunk)
        for tk in chunk:
            try:
                if n == 1:
                    clo = raw.get("Close")
                    vol = raw.get("Volume") if "Volume" in raw.columns else None
                    if clo is None:
                        clo = raw.iloc[:, 0] if not raw.empty else pd.Series(dtype=float)
                elif isinstance(raw.columns, pd.MultiIndex):
                    if "Close" in raw.columns.get_level_values(0):
                        clo = raw["Close"].get(tk, pd.Series(dtype=float))
                        vol = (raw["Volume"].get(tk, pd.Series(dtype=float))
                               if "Volume" in raw.columns.get_level_values(0) else None)
                    elif tk in raw.columns:
                        sub = raw[tk]
                        clo = sub.get("Close", sub.iloc[:, 0]) if hasattr(sub, "get") else sub
                        vol = sub.get("Volume") if hasattr(sub, "get") else None
                    else:
                        clo = pd.Series(dtype=float)
                        vol = None
                else:
                    clo = raw.get(tk, pd.Series(dtype=float)) if tk in raw.columns else pd.Series(dtype=float)
                    vol = None
                clo = clo.dropna() if clo is not None else pd.Series(dtype=float)
                vv = vol.dropna() if vol is not None and not getattr(vol, "empty", True) else None
                clo = _histlib_normalize_ts_index(clo)
                vv = _histlib_normalize_ts_index(vv) if vv is not None else None
                if clo.empty:
                    print(f"  [HistLib] {tk}: serie Close vuota")
                    continue
                if vv is not None and not vv.empty:
                    try:
                        vv = vv.reindex(clo.index)
                    except Exception:
                        pass
                _histlib_save_cv_pair(tk, clo, vv)
                out[tk] = {"close": clo, "volume": vv}
            except Exception as _one:
                print(f"  [HistLib] {tk} parse KO: {_one}")

    # yfinance può svuotare ^XBI nel batch: riprova i simboli Yahoo noti.
    if "^XBI" in need:
        xf = out.get("^XBI")
        if (xf is None or not xf.get("close")
                or getattr(xf["close"], "empty", True)):
            for sym_fb in ("^XBI", "XBI"):
                try:
                    raw_fb = yf_mod.download(
                        sym_fb, period=period, auto_adjust=True, progress=False,
                    )
                    if raw_fb is None or getattr(raw_fb, "empty", True):
                        continue
                    if "Close" in raw_fb.columns:
                        clo = raw_fb["Close"].dropna().astype(float)
                    else:
                        clo = raw_fb.iloc[:, 0].dropna().astype(float)
                    vol = (raw_fb["Volume"].dropna().astype(float)
                           if "Volume" in raw_fb.columns else None)
                    clo = _histlib_normalize_ts_index(clo)
                    vv = (_histlib_normalize_ts_index(vol)
                          if vol is not None and not vol.empty else None)
                    if clo.empty:
                        continue
                    if vv is not None and not vv.empty:
                        try:
                            vv = vv.reindex(clo.index)
                        except Exception:
                            pass
                    _histlib_save_cv_pair("^XBI", clo, vv)
                    out["^XBI"] = {"close": clo, "volume": vv}
                    if sym_fb != "^XBI":
                        print(f"  [HistLib] ^XBI: serie lunga da «{sym_fb}» (SPDR).", flush=True)
                    break
                except Exception as _xfe:
                    print(f"  [HistLib] ^XBI fallback {sym_fb}: {_xfe}", flush=True)

    if not _price_tail_merge_disabled():
        try:
            _hl_lag = _histlib_min_lag_days()
        except Exception:
            _hl_lag = 3
        _stale_tail: list[str] = []
        for _tk in tickers:
            if not _tk or not str(_tk).strip():
                continue
            _tu = str(_tk).strip().upper()
            if _tu not in out:
                continue
            if _histlib_ticker_series_stale(_tu, min_lag_days=_hl_lag):
                _stale_tail.append(_tu)
        if _stale_tail:
            try:
                import yfinance as _yf_hl_tail
            except ImportError:
                _yf_hl_tail = None
            if _yf_hl_tail is not None:
                _histlib_tail_merge_tickers(_stale_tail, _yf_hl_tail)

    return out


def _histlib_min_lag_days() -> int:
    """Giorni senza nuova barra prima di aggiornare (solo coda Yahoo, non storico intero)."""
    try:
        return max(0, int(os.environ.get("HISTLIB_MIN_LAG_DAYS", "3").strip() or "3"))
    except ValueError:
        return 3


def _histlib_incremental_only() -> bool:
    """Default on: serie pickle preservate; solo tail-merge se obsolete (``HISTLIB_INCREMENTAL_ONLY=0`` off)."""
    v = os.environ.get("HISTLIB_INCREMENTAL_ONLY", "1").strip().lower()
    return v not in ("0", "false", "no", "off")


def _histlib_refresh_on_enrich_enabled() -> bool:
    v = os.environ.get("HISTLIB_REFRESH_ON_ENRICH", "1").strip().lower()
    return v not in ("0", "false", "no", "off")


def _histlib_tail_merge_tickers(tickers: list[str], yf_mod) -> int:
    """
    Aggiorna solo le ultime sedute (``PRICE_TAIL_MERGE_PERIOD``) sui pickle HistLib esistenti.
    Lo storico lungo in ``data/price_cache/*_HISTCV_max_cv.pkl`` non viene riscaricato.
    """
    if _price_tail_merge_disabled() or not tickers:
        return 0
    mini_p = _price_tail_merge_period()
    _CHUNK = 50
    merged = 0
    _uniq: list[str] = []
    _seen: set[str] = set()
    for _t in tickers:
        _tu = str(_t or "").strip().upper()
        if not _tu or _tu in _seen:
            continue
        _seen.add(_tu)
        if _histlib_load_cv_pair(_tu) is None:
            continue
        _uniq.append(_tu)
    if not _uniq:
        return 0

    for ci_start in range(0, len(_uniq), _CHUNK):
        chunk = _uniq[ci_start: ci_start + _CHUNK]
        try:
            raw = yf_mod.download(
                chunk if len(chunk) > 1 else chunk[0],
                period=mini_p,
                auto_adjust=True,
                group_by="ticker",
                progress=False,
            )
        except Exception as _te:
            print(f"  [HistLib] Tail-merge errore batch: {_te}", flush=True)
            continue
        if raw is None or getattr(raw, "empty", True):
            continue
        for _tk in chunk:
            _cached = _histlib_load_cv_pair(_tk)
            if _cached is None:
                continue
            try:
                c_mini, v_mini = _yf_parse_close_vol_from_raw(raw, _tk, chunk)
            except Exception:
                continue
            c_old = _histlib_normalize_ts_index(_cached["close"])
            v_old = _cached.get("volume")
            v_old = _histlib_normalize_ts_index(v_old) if v_old is not None else None
            nc = _yf_combine_price_series(c_old, c_mini, trim_calendar_days=None)
            if v_old is not None and not getattr(v_old, "empty", True):
                nv = _yf_combine_price_series(v_old, v_mini, trim_calendar_days=None)
            elif v_mini is not None and not getattr(v_mini, "empty", True):
                nv = v_mini.copy()
            else:
                nv = None
            try:
                if nv is not None and not getattr(nv, "empty", True):
                    nv = nv.reindex(nc.index)
            except Exception:
                pass
            _histlib_save_cv_pair(_tk, nc, nv)
            merged += 1

    if merged:
        print(
            f"[HistLib] Tail-merge `{mini_p}` su {merged}/{len(_uniq)} ticker "
            f"(storico preservato, solo barre recenti).",
            flush=True,
        )
    return merged


def _histlib_ensure_tickers_updated(
    tickers: list[str],
    yf_mod,
    *,
    force: bool = False,
    min_lag_days: int | None = None,
) -> list[str]:
    """
    HistLib Close/Volume: scarico completo solo se manca il pickle; se obsoleto → solo coda.
    Con ``force=True`` e ``HISTLIB_INCREMENTAL_ONLY=0`` elimina pickle e riscarica tutto.
    """
    _lag = int(min_lag_days) if min_lag_days is not None else _histlib_min_lag_days()
    _uniq: list[str] = []
    _seen: set[str] = set()
    for _t in tickers or []:
        _tu = str(_t or "").strip().upper()
        if not _tu or _tu in _seen:
            continue
        _seen.add(_tu)
        _uniq.append(_tu)
    if not _uniq:
        return []

    _missing: list[str] = []
    _stale: list[str] = []
    _ser_cache: dict = {}
    _full_redownload = force and not _histlib_incremental_only()

    for _tu in _uniq:
        if _full_redownload:
            try:
                _p = _histlib_cv_pickle_path(_tu)
                if os.path.exists(_p):
                    os.remove(_p)
            except Exception:
                pass
            _missing.append(_tu)
            continue
        if _histlib_load_cv_pair(_tu) is None:
            _missing.append(_tu)
        elif _histlib_ticker_series_stale(
            _tu, min_lag_days=_lag, ser_cache=_ser_cache
        ):
            _stale.append(_tu)

    _touched: list[str] = []
    if _missing:
        _yf_batch_histlib_close_volume(_missing, yf_mod)
        _touched.extend(_missing)
    if _stale:
        _histlib_tail_merge_tickers(_stale, yf_mod)
        _touched.extend(_stale)
    return _touched


def _histlib_last_trade_date_before(ser: "pd.Series", cal_end) -> object | None:
    """Ultima data indice ≤ cal_end (cal_end è date/datetime/str)."""
    if ser is None or getattr(ser, "empty", True):
        return None
    try:
        ts = pd.Timestamp(cal_end).normalize()
    except Exception:
        return None
    try:
        raw_idx = ser.index
    except Exception:
        return None

    # Percorso veloce: O(log n) su indice temporale ordinato (prima: O(n) scan Python
    # × migliaia di righe HistLib → minuti e utente interrompe con Ctrl+C).
    try:
        if isinstance(raw_idx, pd.DatetimeIndex):
            idn = raw_idx
            if getattr(idn, "tz", None) is not None:
                idn = idn.tz_convert("UTC").tz_localize(None)
            idn = idn.normalize()
        else:
            idn = pd.DatetimeIndex(
                pd.to_datetime(raw_idx, errors="coerce")).normalize()
        idn = idn[~idn.isna()]
        if len(idn) == 0:
            return None
        if not idn.is_monotonic_increasing:
            idn = idn.sort_values()
        pos = int(idn.searchsorted(ts, side="right"))
        if pos <= 0:
            return None
        cand = idn[pos - 1]
        return cand.date() if hasattr(cand, "date") else cand
    except Exception:
        pass

    try:
        idx_dates = sorted(raw_idx)
    except Exception:
        return None
    last = None
    for d in idx_dates:
        try:
            dd = pd.Timestamp(d).normalize()
        except Exception:
            continue
        if dd <= ts:
            last = dd.date() if hasattr(dd, "date") else d
        else:
            break
    return last


def _compute_event_study_car(
        stock_close_ser: "pd.Series",
        mkt_close_ser: "pd.Series | None",
        completion_date_ts,
        *,
        est_bd: int | None = None,
        gap_bd: int | None = None,
        pre_bd: int | None = None,
        post_bd: int | None = None,
) -> dict:
    """
    Event study: R_i,t = α + β R_XBI,t + ε; AR = R_i − (α+βR_m); CAR(τ) somma AR
    dalla prima barra della finestra evento fino a τ (giorni di borsa vs anchor).
    Anchor = ultima sessione con data ≤ completion (stessa logica path prezzi vs CD).
    """
    import numpy as np

    est_bd = int(est_bd if est_bd is not None else _CAR_EST_BD)
    gap_bd = int(gap_bd if gap_bd is not None else _CAR_GAP_BD)
    pre_bd = int(pre_bd if pre_bd is not None else _CAR_PRE_BD)
    post_bd = int(post_bd if post_bd is not None else _CAR_POST_BD)

    null = {
        "schema": _HISTLIB_EVENT_STUDY_SCHEMA,
        "ok": False,
        "reason": "init",
        "alpha": None,
        "beta": None,
        "r2": None,
        "n_est": 0,
        "est_idx_start": None,
        "est_idx_end": None,
        "anchor_trade_date": None,
        "car_cum_pct": {},
        "car_jump_0_pp": None,
        "params": {"est_bd": est_bd, "gap_bd": gap_bd, "pre_bd": pre_bd, "post_bd": post_bd},
    }

    if mkt_close_ser is None or getattr(mkt_close_ser, "empty", True):
        null["reason"] = "no_xbi"
        return null
    if stock_close_ser is None or getattr(stock_close_ser, "empty", True):
        null["reason"] = "no_stock"
        return null

    try:
        cd = pd.Timestamp(completion_date_ts).normalize()
    except Exception:
        null["reason"] = "bad_cd"
        return null

    sc = _histlib_normalize_ts_index(stock_close_ser).astype(float)
    xc = _histlib_normalize_ts_index(mkt_close_ser).astype(float)
    # Forza vettori 1D (cache yfinance / pickle possono lasciare values shape (n,1)).
    sc = pd.Series(np.ravel(np.asarray(sc, dtype=float)), index=sc.index, name="s")
    xc = pd.Series(np.ravel(np.asarray(xc, dtype=float)), index=xc.index, name="m")
    mf = pd.DataFrame({"s": sc, "m": xc}).sort_index().dropna(how="any")
    if len(mf) < max(est_bd + gap_bd + pre_bd + 20, 80):
        null["reason"] = "short_history"
        return null

    ax = mf.index <= cd
    if not ax.any():
        null["reason"] = "no_pre_cd_bars"
        return null
    anchor_ts = mf.index[ax][-1]
    try:
        anchor_loc = int(mf.index.get_loc(anchor_ts))
    except Exception:
        null["reason"] = "anchor_loc"
        return null
    if isinstance(anchor_loc, slice):
        anchor_loc = anchor_loc.start

    j_ev0 = anchor_loc - pre_bd
    j_ev1 = anchor_loc + post_bd
    j_est_hi = anchor_loc - pre_bd - gap_bd
    j_est_lo = j_est_hi - est_bd + 1
    if j_ev0 < 1 or j_est_lo < 1 or j_est_hi < j_est_lo:
        null["reason"] = "window_oob"
        return null

    rs = mf["s"].pct_change()
    rm = mf["m"].pct_change()
    est_mask = (np.arange(len(mf)) >= j_est_lo) & (np.arange(len(mf)) <= j_est_hi)
    y = rs.values[est_mask]
    x = rm.values[est_mask]
    valid = np.isfinite(y) & np.isfinite(x)
    yv = y[valid]
    xv = x[valid]
    if len(yv) < max(30, est_bd // 4):
        null["reason"] = "sparse_est"
        return null

    X = np.column_stack([np.ones(len(xv)), xv])
    try:
        beta_hat, _, _, _ = np.linalg.lstsq(X, yv, rcond=None)
        alpha_f, beta_f = float(beta_hat[0]), float(beta_hat[1])
    except Exception:
        null["reason"] = "ols_fail"
        return null

    y_fit = X @ beta_hat
    ss_res = float(np.sum((yv - y_fit) ** 2))
    y_mean = float(np.mean(yv))
    ss_tot = float(np.sum((yv - y_mean) ** 2))
    r2 = (1.0 - ss_res / ss_tot) if ss_tot > 1e-18 else None

    ar = rs.values - (alpha_f + beta_f * rm.values)
    ar = np.where(np.isfinite(ar), ar, np.nan)

    car_cum_pct: dict[str, float] = {}
    for tau in range(-pre_bd, post_bd + 1):
        j_to = anchor_loc + tau
        if j_to < j_ev0 or j_to > j_ev1:
            continue
        seg = ar[j_ev0:j_to + 1]
        if np.any(np.isfinite(seg)):
            car_cum_pct[str(tau)] = round(float(np.nansum(seg)) * 100.0, 4)

    jump = None
    try:
        a_ = car_cum_pct.get("0")
        b_ = car_cum_pct.get("-1")
        if a_ is not None and b_ is not None:
            jump = round(float(a_) - float(b_), 4)
    except Exception:
        pass

    out = {
        "schema": _HISTLIB_EVENT_STUDY_SCHEMA,
        "ok": True,
        "reason": None,
        "alpha": round(alpha_f, 6),
        "beta": round(beta_f, 6),
        "r2": round(r2, 4) if r2 is not None else None,
        "n_est": int(len(yv)),
        "est_idx_start": int(j_est_lo),
        "est_idx_end": int(j_est_hi),
        "anchor_trade_date": str(anchor_ts.date()),
        "car_cum_pct": car_cum_pct,
        "car_jump_0_pp": jump,
        "params": {"est_bd": est_bd, "gap_bd": gap_bd, "pre_bd": pre_bd, "post_bd": post_bd},
    }
    return out


def _car_curve_pts_for_calibration(ticker: str, cd, xbi_ser: "pd.Series | None") -> dict | None:
    """Ritorna {tau: CAR% cum} solo per _CURVE_OFFSETS; None se non stimabile."""
    if xbi_ser is None:
        return None
    import pandas as _pd
    try:
        s = _pcache_series_for_calibration(str(ticker).strip().upper())
    except Exception:
        s = None
    if s is None or s.empty:
        return None
    car = _compute_event_study_car(s, xbi_ser, cd)
    if not car.get("ok"):
        return None
    ccp = car.get("car_cum_pct") or {}
    out: dict[int, float | None] = {}
    for off in _CURVE_OFFSETS:
        v = ccp.get(str(off))
        out[off] = float(v) if v is not None else None
    if sum(1 for v in out.values() if v is not None) < 4:
        return None
    return out


def _histlib_metrics_at(close_ser, vol_ser, xbi_close_ser,
                        ref_calendar_date,
                        completion_date_for_days) -> dict:
    """
    Calcolo metriche punto decisionale storico alla data ref_calendar_date (calendario)
    usando **solo** barre Close/Volume/XBI ≤ ref_calendar_date.
    """
    import numpy as np

    out: dict = {k: None for k in _MODEL_HIST_COVERAGE_KEYS}
    out["close_asof_date"] = None
    out["exp_move_pct"] = None

    cls = close_ser
    vol = vol_ser if vol_ser is not None else pd.Series(dtype=float)
    try:
        end_ts = pd.Timestamp(ref_calendar_date).normalize()
    except Exception:
        return out

    asof_trade = _histlib_last_trade_date_before(cls, end_ts)
    out["close_asof_date"] = (
        str(asof_trade) if asof_trade is not None else None)
    if asof_trade is None:
        return out

    def _subset(s):
        if s is None or getattr(s, "empty", True):
            return pd.Series(dtype=float)
        try:
            end_td = pd.Timestamp(asof_trade).normalize()
            idx = s.index
            if (isinstance(idx, pd.DatetimeIndex)
                    and idx.is_monotonic_increasing
                    and getattr(idx, "tz", None) is None):
                try:
                    pos = int(idx.normalize().searchsorted(end_td, side="right"))
                    if pos <= 0:
                        return pd.Series(dtype=float)
                    return s.iloc[:pos].astype(float).dropna()
                except Exception:
                    pass
            return s.loc[s.index <= end_td].astype(float).dropna()
        except Exception:
            return pd.Series(dtype=float)

    c = _subset(cls)
    v = _subset(vol)
    if c.empty:
        return out

    def _sl_n(n):
        try:
            s = c.tail(n)
            if len(s) < max(3, n // 2):
                return None
            x = np.arange(len(s), dtype=float)
            y = s.values.astype(float)
            p0 = y[0] if y[0] > 0 else 1.0
            return round(float(np.polyfit(x, (y / p0 - 1.0) * 100.0, 1)[0]), 4)
        except Exception:
            return None

    def _rsi_here():
        try:
            tail = c.tail(30)
            if len(tail) < 15:
                return None
            d = tail.diff().dropna()
            g = d.clip(lower=0).rolling(14).mean()
            lv = (-d.clip(upper=0)).rolling(14).mean()
            rs = g / lv.replace(0, float("nan"))
            rsi = (100 - 100 / (1 + rs)).iloc[-1]
            return float(rsi) if pd.notna(rsi) else None
        except Exception:
            return None

    def _vrat_here():
        try:
            if len(v) < 20:
                return None
            a5 = float(v.tail(5).mean())
            a15 = float(v.tail(20).head(15).mean())
            return round(a5 / a15, 3) if a15 > 0 else None
        except Exception:
            return None

    def _vacl_here():
        try:
            if len(v) < 10:
                return None
            return round(float(v.tail(5).mean()) / float(v.head(5).mean()), 2)
        except Exception:
            return None

    def _runup_here(n_days):
        try:
            tail = c.tail(n_days)
            if len(tail) < max(5, n_days // 3):
                return None
            return round((float(tail.iloc[-1]) / float(tail.iloc[0]) - 1.0) * 100.0, 1)
        except Exception:
            return None

    def _ath_here():
        try:
            if len(c) < 20:
                return None
            hi = float(c.tail(252).max())
            cur = float(c.iloc[-1])
            return round(cur / hi, 3) if hi > 0 else None
        except Exception:
            return None

    def _exc_here():
        if xbi_close_ser is None or getattr(xbi_close_ser, "empty", True):
            return None
        try:
            s_tk = _sl_n45()
            xc = xbi_close_ser
            end_td_x = pd.Timestamp(asof_trade).normalize()
            ix = xc.index
            if (isinstance(ix, pd.DatetimeIndex)
                    and ix.is_monotonic_increasing
                    and getattr(ix, "tz", None) is None):
                try:
                    px = int(ix.normalize().searchsorted(end_td_x, side="right"))
                    xv = xc.iloc[:px].tail(45) if px > 0 else xc.iloc[:0]
                except Exception:
                    xv = xc.loc[xc.index <= end_td_x].tail(45)
            else:
                xv = xc.loc[xc.index <= end_td_x].tail(45)
            if len(xv) < 5 or s_tk is None:
                return None
            x_arr = np.arange(len(xv), dtype=float)
            yv = xv.values.astype(float)
            p0 = yv[0] if yv[0] > 0 else 1.0
            sx = round(float(np.polyfit(x_arr, (yv / p0 - 1.0) * 100.0, 1)[0]), 4)
            return round(s_tk - sx, 4)
        except Exception:
            return None

    def _sl_n45():
        try:
            s = c.tail(45)
            if len(s) < 5:
                return None
            x = np.arange(len(s), dtype=float)
            y = s.values.astype(float)
            p0 = y[0] if y[0] > 0 else 1.0
            return round(float(np.polyfit(x, (y / p0 - 1.0) * 100.0, 1)[0]), 4)
        except Exception:
            return None

    def _vpd_here(n=20):
        try:
            if len(v) < n or len(c) < n:
                return None
            p_tail = c.tail(n)
            if len(p_tail) < max(3, n // 2):
                return None
            x_arr = np.arange(len(p_tail), dtype=float)
            y_arr = p_tail.values.astype(float)
            p0p = y_arr[0] if y_arr[0] > 0 else 1.0
            p_sl = float(np.polyfit(x_arr, (y_arr / p0p - 1.0) * 100.0, 1)[0])
            raw_vol = v.tail(n)
            if len(raw_vol) < max(3, n // 2):
                return None
            xv = np.arange(len(raw_vol), dtype=float)
            yv = raw_vol.values
            mean_v = float(yv.mean() or 1.0)
            v_sl = float(np.polyfit(xv, yv / mean_v, 1)[0]) * 100.0
            if p_sl < -0.3 and v_sl > 0.5:
                return +1
            if p_sl > 0.3 and v_sl < -0.5:
                return -1
            return 0
        except Exception:
            return None

    out["slope_45d"] = _sl_n45()
    out["slope_5d"] = _sl_n(5) if len(c) >= 5 else None
    out["slope_20d"] = _sl_n(20) if len(c) >= 10 else None

    out["exc_slope_vs_XBI"] = _exc_here()
    out["rsi_14"] = _rsi_here()
    out["vol_ratio"] = _vrat_here()
    out["vol_accel"] = _vacl_here()
    out["run_up_30d"] = _runup_here(30) if len(c) >= 30 else None
    out["run_up_7d"] = _runup_here(7) if len(c) >= 7 else None
    # Slope inferito dal run-up 30g + sorgente — coerenti con la cascata di
    # fallback usata nella UI (precatCurve.ts) e nel dict _pred_row. Servono
    # come audit: non sostituiscono slope_5d/slope_20d sopra.
    out["slope_inferred"] = _infer_slope_from_run_up(out["run_up_30d"])
    out["slope_source"]   = _compute_slope_source(
        out["slope_20d"], out["slope_5d"], out["run_up_30d"]
    )
    # Metriche di stabilità della pendenza — driver per entry/exit (Decision Lab).
    # Non alterano pred5/pred5_low/pred5_high; sono informative.
    _ss_metrics = _compute_slope_stability_metrics(
        out["slope_5d"], out["slope_20d"], slope_45d=out.get("slope_45d"),
    )
    out["slope_consistency"]       = _ss_metrics["slope_consistency"]
    out["slope_rotation_flag"]     = _ss_metrics["slope_rotation_flag"]
    out["slope_stability_class"]   = _ss_metrics["slope_stability_class"]
    out["persistence_window_days"] = _ss_metrics["persistence_window_days"]
    out["ath_prox_52wk"] = _ath_here()
    vpd_val = _vpd_here()
    out["vol_price_div"] = vpd_val
    # Opzioni: no ricostruzione storica gratuita affidabile qui
    out["pcr_options"] = None

    # Giorni al completion dalla ref (solo informativa)
    try:
        cd = pd.Timestamp(completion_date_for_days).normalize().date()
        rd = pd.Timestamp(asof_trade).normalize().date()
        out["calendar_days_to_completion"] = (cd - rd).days
    except Exception:
        out["calendar_days_to_completion"] = None

    return out


def _model_hist_coverage_keys_for_metrics(metrics: dict | None) -> tuple[str, ...]:
    """Slot inclusi nel conteggio copertura: PCR solo se valorizzato in ``metrics``."""
    if not isinstance(metrics, dict):
        return _MODEL_HIST_COVERAGE_KEYS_CORE
    p = metrics.get("pcr_options")
    if p is None:
        return _MODEL_HIST_COVERAGE_KEYS_CORE
    if isinstance(p, str):
        ps = str(p).strip()
        if not ps or ps.upper() == "NA":
            return _MODEL_HIST_COVERAGE_KEYS_CORE
    return _MODEL_HIST_COVERAGE_KEYS


def _histlib_coverage_str(metrics: dict) -> tuple[int, str]:
    keys = _model_hist_coverage_keys_for_metrics(metrics)
    ok = sum(1 for k in keys
             if metrics.get(k) is not None
             and metrics.get(k) != ""             # sicurezza
             and str(metrics.get(k)).upper() != "NA")
    return ok, f"{ok}/{len(keys)}"


MODEL_APPLICABILITY_MIN_DEFAULT = 8
"""Soglia minima di slot presenti (denominatore = 11 senza PCR, 12 con PCR nei ``metrics``)
per considerare l'inferenza del modello «Applicabile». Override: env MODEL_APPLICABILITY_MIN_INPUTS."""


def _model_applicability_min_inputs() -> int:
    try:
        raw = os.environ.get("MODEL_APPLICABILITY_MIN_INPUTS", "").strip()
        mn = int(raw) if raw else MODEL_APPLICABILITY_MIN_DEFAULT
    except ValueError:
        mn = MODEL_APPLICABILITY_MIN_DEFAULT
    n_tot = len(_MODEL_HIST_COVERAGE_KEYS)
    return max(0, min(n_tot, mn))


def _model_metric_dict_from_ensemble_signals(
    exc_slope_vs_XBI,
    slope_45d,
    rsi_14,
    vol_ratio,
    vol_accel,
    slope_5d,
    slope_20d,
    run_up_30d,
    run_up_7d,
    ath_prox_52wk,
    vol_price_div,
    pcr_options=None,
) -> dict:
    """Dict allineato a ``_MODEL_HIST_COVERAGE_KEYS`` (``n/max`` nella label da ``_histlib_coverage_str``)."""
    _vpd = None
    if vol_price_div is not None:
        try:
            _vpd = int(vol_price_div)
        except (TypeError, ValueError):
            _vpd = vol_price_div
    _pcr = pcr_options
    if _pcr is not None and not isinstance(_pcr, bool):
        try:
            _pcr = float(_pcr)
        except (TypeError, ValueError):
            pass
    return {
        "exc_slope_vs_XBI": exc_slope_vs_XBI,
        "slope_45d": slope_45d,
        "rsi_14": rsi_14,
        "vol_ratio": vol_ratio,
        "vol_accel": vol_accel,
        "slope_5d": slope_5d,
        "slope_20d": slope_20d,
        "run_up_30d": run_up_30d,
        "run_up_7d": run_up_7d,
        "ath_prox_52wk": ath_prox_52wk,
        "vol_price_div": _vpd,
        "pcr_options": _pcr,
    }


def model_input_applicability_report(
    metrics: dict | None,
    *,
    pred_dataset_incomplete: bool = False,
) -> dict:
    """
    Riepiloga copertura input coerente con ``_histlib_coverage_str``: fino a 11 slot senza PCR
    nei dati storici, 12 con ``pcr_options`` valorizzato.
    ``Applicabile`` richiede `n_ok ≥ min(env MODEL_APPLICABILITY_MIN_INPUTS, |pool|)`
    e ``pred_dataset_incomplete`` falso quando il flag è noto (es. curve numeriche).
    """
    m = metrics if isinstance(metrics, dict) else {}
    keys = _model_hist_coverage_keys_for_metrics(m)
    n_tot = len(keys)
    n_ok, label = _histlib_coverage_str(m)
    missing = n_tot - n_ok
    mn = min(_model_applicability_min_inputs(), n_tot)
    trusted = (n_ok >= mn) and (not pred_dataset_incomplete)
    return {
        "model_inputs_present_n": n_ok,
        "model_inputs_missing_n": missing,
        "model_inputs_label": label,
        "model_inputs_pool_n": n_tot,
        "model_inferenza_affidabile": trusted,
        "model_inferenza_stato": "ok" if trusted else "dati_insufficienti",
        "model_inferenza_stato_it": "Applicabile" if trusted else "Solo esplorativa",
    }


def _model_accuracy_min_present_slots() -> int:
    """
    Soglia minima di ``model_inputs_present_n`` per le **statistiche aggregate**
    (RMSE, % OK, Casistiche, Retro/Modello). Confrontata al conteggio ``n_ok`` dalla
    stessa copertura (11 slot senza PCR, 12 con PCR).

    Default = ``len(_MODEL_HIST_COVERAGE_KEYS_CORE)`` (**11**) così PastCatalyst / Completati
    con tutti i segnali prezzo+XBI possono essere eleggibili (PCR non ricostruita sullo storico).

    Override: ``MODEL_ACCURACY_MIN_PRESENT`` (clamp 1…12).
    """
    n_tot = len(_MODEL_HIST_COVERAGE_KEYS)
    raw = os.environ.get("MODEL_ACCURACY_MIN_PRESENT", "").strip()
    if raw:
        try:
            return max(1, min(n_tot, int(raw)))
        except ValueError:
            pass
    return len(_MODEL_HIST_COVERAGE_KEYS_CORE)


def _model_inputs_full_pool_coverage(row: dict | None) -> bool:
    """
    Copertura **perfetta** degli input ensemble: ``model_inputs_present_n`` ≥
    ``model_inputs_pool_n`` (etichetta tipo 11/11 senza PCR nello storico, 12/12 se
    ``pcr_options`` è nel pool e valorizzato). Esclude righe col dataset numerico incompleto.
    """
    if not isinstance(row, dict):
        return False
    if row.get("pred_dataset_incomplete"):
        return False
    pn = row.get("model_inputs_present_n")
    pool = row.get("model_inputs_pool_n")
    if pn is None or pool is None:
        return False
    try:
        pi, pl = int(pn), int(pool)
    except (TypeError, ValueError):
        return False
    return pl >= 1 and pi >= pl


def _sponsor_match_exact_for_model(row: dict | None) -> bool:
    """Sponsor Exact (match perfetto sullo studio)."""
    if not isinstance(row, dict):
        return False
    sm = str(row.get("sponsor_match") or "").strip().upper()
    return sm == "EXACT"


def _model_exact_and_full_inputs_eligible(row: dict | None) -> bool:
    """
    Coorte «perfect match» per aggregati e IPO: **Exact** + tutti gli slot del pool
    (11/11 o 12/12 secondo ``model_inputs_label``).
    """
    return (
        _model_inputs_full_pool_coverage(row)
        and _sponsor_match_exact_for_model(row)
    )


def _model_accuracy_metrics_eligible(row: dict | None) -> bool:
    """
    ``True`` se la riga ha abbastanza input per confrontare attendibilmente il modello:
    dataset predizione non incompleto e ``model_inputs_present_n`` ≥
    ``_model_accuracy_min_present_slots()`` (default allineato a 11 slot senza PCR).
    Righe senza ``model_inputs_present_n`` (JSON legacy, calibrazione non arricchita) sono escluse.
    """
    if not isinstance(row, dict):
        return False
    if row.get("pred_dataset_incomplete"):
        return False
    need = _model_accuracy_min_present_slots()
    pn = row.get("model_inputs_present_n")
    if pn is None:
        return False
    try:
        return int(pn) >= need
    except (TypeError, ValueError):
        return False


def _numeric_score_for_agg(val) -> float | None:
    """Score / metrica numerica per aggregate (pandas/numpy/Python)."""
    if val is None:
        return None
    if isinstance(val, bool):
        return None
    try:
        if pd.isnull(val):  # type: ignore[arg-type]
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(val, (int, float)):
        try:
            return float(val)
        except (OverflowError, TypeError, ValueError):
            return None
    try:
        import numpy as np
        if isinstance(val, np.generic):
            return float(val.item())
    except Exception:
        pass
    try:
        return float(val)
    except (TypeError, ValueError):
        return None


def _model_timepoint_aff_sample_eligible(row: dict | None) -> bool:
    """
    Filtro campione per la tabella «affidabilità per timepoint» (media score v4).

    **Default (env assente):** campione **ampliato** (almeno uno score v4, esclusa non quotata
    al CD) così il grafico non resta vuoto/flat sui dati reali.

    Override env ``AFF_TIMEPOINT_POOL``:
      • ``exact_full`` | ``perfect`` — sponsor **Exact** + pool input completo (11/11 o 12/12).
      • ``strict`` | ``rmse`` | ``accuracy`` — ``_model_accuracy_metrics_eligible``.
      • ``extended`` | ``wide`` | ``loose`` — come il default (esplicito).
    """
    if not isinstance(row, dict):
        return False
    _mode = os.environ.get("AFF_TIMEPOINT_POOL", "").strip().lower()
    if _mode in ("exact_full", "perfect", "perfect_match"):
        return _model_exact_and_full_inputs_eligible(row)
    if _mode in ("strict", "rmse", "accuracy"):
        return _model_accuracy_metrics_eligible(row)

    def _extended_pool():
        if row.get("non_quotata_al_tempo"):
            return False
        _keys = (
            "score_v4",
            "score_v4_t5",
            "score_v4_t3",
            "score_v4_t1",
            "score_v4_post3",
            "score_v4_post5",
            "score_v4_post10",
            "score_v4_post30",
        )
        return any(_numeric_score_for_agg(row.get(k)) is not None for k in _keys)

    if _mode in ("extended", "wide", "loose"):
        return _extended_pool()
    # default vuoto → stesso comportamento «extended»
    return _extended_pool()


def _histlib_row_key(ticker: str, completion_date_iso: str) -> str:
    return f"{str(ticker).strip().upper()}|{completion_date_iso[:10]}"


_HISTLIB_CLI_DATE_FALLBACK_COLS = (
    "completion_date",
    "primary_completion_date",
    "PrimaryCompletionDate",
    "CompletionDate",
    "study_completion_date",
    "estimated_completion_date",
    "end_date",
)


def _histlib_clinical_completion_index(clinical_df) -> dict[str, dict]:
    """
    Mappa ticker|CD → metadati (NCT, fase, sponsor, titolo) come in enrich HistLib.
    Stesse colonne data usate altrove nei fogli clinical (allineamento a ticker_studies).
    """
    idx: dict[str, dict] = {}
    if clinical_df is None or getattr(clinical_df, "empty", True):
        return idx
    cols = list(clinical_df.columns)
    ticker_col = next((c for c in ("ticker", "symbol", "Ticker") if c in cols), None)
    date_col = next((c for c in _HISTLIB_CLI_DATE_FALLBACK_COLS if c in cols), None)
    if not date_col:
        return idx

    nct_col = next((c for c in ("nct_id", "NCTId", "nct_number") if c in cols), None)
    phase_col = next((c for c in ("phase", "Phase", "phases", "study_phase") if c in cols), None)
    title_col = next((c for c in ("study_title", "title", "brief_title", "BriefTitle")
                      if c in cols), None)
    sponsor_col = next((c for c in ("lead_sponsor", "sponsor") if c in cols), None)
    sm_col = None
    for c in ("sponsor_match", "match_type"):
        if c in cols:
            sm_col = c
            break

    for _, crow in clinical_df.iterrows():
        tk = ""
        if ticker_col:
            tk = str(crow.get(ticker_col) or "").strip().upper()
        cd = _normalize_completion_date_ca(crow.get(date_col))
        if not tk or cd is None:
            continue
        k = _histlib_row_key(tk, cd.isoformat())
        rec: dict = {}
        if nct_col:
            nid = str(crow.get(nct_col) or "").strip().upper()
            if nid.startswith("NCT"):
                rec["nct_id"] = nid
        if phase_col:
            rec["phase_ct"] = _phase_str_norm(crow.get(phase_col))
        if title_col:
            t = str(crow.get(title_col) or "").strip()
            rec["study_title_short"] = (t[:240] + ("…" if len(t) > 240 else "")) if t else ""
        if sponsor_col:
            lp = str(crow.get(sponsor_col) or "").strip()
            if lp:
                rec["lead_sponsor"] = lp
        if sm_col:
            sm = str(crow.get(sm_col) or "").strip()
            if sm:
                rec["sponsor_match"] = sm
        prev = idx.get(k)
        if prev is None or (rec.get("nct_id") and not prev.get("nct_id")):
            if prev:
                merger = dict(prev)
                for _kk, vv in rec.items():
                    if vv:
                        merger[_kk] = vv
                idx[k] = merger
            else:
                idx[k] = rec
    return idx


def _histlib_enrich_pairs_from_clinical(
        pair_rows: list[dict],
        clinical_df,
        clinical_index: dict[str, dict] | None = None) -> list[dict]:
    """
    Associa da clinical_df (chiave ticker+completion): NCT, fase, titolo breve,
    lead sponsor, **sponsor_match** quando le colonne esistono (stesso discriminante
    del baseline «controllo unrelated» Exact+NASDAQ nella calibrazione).
    """
    if not pair_rows:
        return pair_rows
    idx = clinical_index if clinical_index is not None else _histlib_clinical_completion_index(
        clinical_df)
    if not idx:
        return pair_rows

    for pr in pair_rows:
        kk = _histlib_row_key(pr["ticker"], pr["completion_date_iso"])
        ext = idx.get(kk)
        if not ext:
            continue
        if ext.get("nct_id") and not str(pr.get("nct_id") or "").startswith("NCT"):
            pr["nct_id"] = ext["nct_id"]
        ext_ph = ext.get("phase_ct")
        if ext_ph:
            prev_ph = str(pr.get("phase_normalized") or "")
            ph_use = ext_ph if (len(ext_ph) >= len(prev_ph)) else prev_ph
            pr["phase_normalized"] = ph_use
            pr["phase_num"] = _ensemble_phase_num(ph_use)
        if ext.get("study_title_short") and not pr.get("study_title_short"):
            pr["study_title_short"] = ext["study_title_short"]
        if ext.get("lead_sponsor") and not pr.get("lead_sponsor"):
            pr["lead_sponsor"] = ext["lead_sponsor"]
        ext_sm = ext.get("sponsor_match")
        if ext_sm and str(ext_sm).strip():
            pr["sponsor_match"] = str(ext_sm).strip()
    return pair_rows


def _gather_hist_library_pair_rows(retro_results: list | None,
                                    sim_rows_past: list | None,
                                    clinical_df=None) -> list[dict]:
    """Righe univoche ticker+completion: fase normalizzata, phase_num, metadati clinici."""
    seen: set[str] = set()
    rows: list[dict] = []

    def _add(tk: str, cd, phase_txt: str = "",
             sponsor_sheet: str = "",
             sponsor_match: str = "",
             study_title_sheet: str = ""):
        if not tk:
            return
        tk_u = tk.strip().upper()
        cd_d = cd
        if hasattr(cd_d, "date"):
            cd_d = cd_d.date()
        elif isinstance(cd_d, str):
            try:
                cd_d = pd.Timestamp(cd_d).date()
            except Exception:
                return
        elif cd_d is None:
            return
        try:
            iso = cd_d.isoformat()
        except Exception:
            return
        kk = _histlib_row_key(tk_u, iso)
        if kk in seen:
            return
        seen.add(kk)
        ph_norm = _phase_str_norm(phase_txt)
        st_ab = ""
        if study_title_sheet:
            t = study_title_sheet.strip()
            st_ab = t[:240] + ("…" if len(t) > 240 else "")
        rows.append({
            "ticker": tk_u,
            "completion_date_iso": iso,
            "phase_normalized": ph_norm,
            "phase_raw": str(phase_txt or "").strip(),
            "phase_num": _ensemble_phase_num(ph_norm),
            "sponsor_sheet": str(sponsor_sheet or "").strip(),
            "sponsor_match": str(sponsor_match or "").strip(),
            "lead_sponsor": "",
            "nct_id": "",
            "study_title_short": st_ab,
        })

    for r in retro_results or []:
        ph = ""
        try:
            ph = str(r.get("phase") or "")
        except Exception:
            pass
        try:
            _ret_sm = str(r.get("sponsor_match") or "").strip()
        except Exception:
            _ret_sm = ""
        _add(str(r.get("ticker")), r.get("comp_date"), ph,
             sponsor_sheet="", sponsor_match=_ret_sm,
             study_title_sheet="")

    for r in sim_rows_past or []:
        if not isinstance(r, dict):
            continue
        cd = _normalize_completion_date_ca(r.get("completion_date"))
        if cd is None:
            cd = r.get("completion_date")
        _sim_sp = str(r.get("sponsor_match") or "").strip()
        _sim_title = ""
        try:
            for _ik in ("study_title", "title", "brief_title"):
                _sim_title = str(r.get(_ik) or "").strip()
                if _sim_title:
                    break
        except Exception:
            pass
        _add(str(r.get("ticker", "")), cd, str(r.get("phase") or ""),
             sponsor_sheet=_sim_sp, sponsor_match=_sim_sp,
             study_title_sheet=_sim_title)

    _cli_idx = _histlib_clinical_completion_index(clinical_df)
    _inc_clin = os.environ.get(
        "HISTLIB_INCLUDE_CLINICAL_COMPLETIONS", "1").strip().lower() not in (
            "0", "false", "no", "off")
    _mx_raw = os.environ.get("HISTLIB_MAX_EXTRA_CLINICAL_PAIRS", "0").strip()
    try:
        _mx_extra = max(0, int(_mx_raw.replace("_", "").replace(",", "")))
    except ValueError:
        _mx_extra = 0

    if _cli_idx and _inc_clin:
        _keys_sorted = sorted(
            _cli_idx.keys(),
            key=lambda z: (z.rsplit("|", 1)[-1] if "|" in z else ""),
            reverse=True,
        )
        _n_added = 0
        for _kk in _keys_sorted:
            if _kk in seen:
                continue
            if _mx_extra and _n_added >= _mx_extra:
                break
            _ext = _cli_idx.get(_kk)
            if _ext is None:
                continue
            _parts = _kk.split("|", 1)
            if len(_parts) != 2:
                continue
            _tkp, _isop = _parts[0], _parts[1]
            try:
                _cdd = pd.Timestamp(_isop).date()
            except Exception:
                continue
            _phx = str(_ext.get("phase_ct") or "")
            _smx = str(_ext.get("sponsor_match") or "").strip()
            _ttx = str(_ext.get("study_title_short") or "").strip()
            _add(_tkp, _cdd, _phx,
                 sponsor_sheet=_smx, sponsor_match=_smx,
                 study_title_sheet=_ttx)
            _n_added += 1
        if _n_added:
            print(f"[HistLib] Completion da clinical_df non già in retro/sim: +{_n_added} coppie"
                  f"{f' (cap HISTLIB_MAX_EXTRA_CLINICAL_PAIRS={_mx_extra})' if _mx_extra else ''}.",
                  flush=True)

    rows = _histlib_enrich_pairs_from_clinical(
        rows, clinical_df, clinical_index=_cli_idx)

    if not rows:
        print("[HistLib] Nessuna coppia ticker|completion da elaborare "
              "(retro/sim/clinical vuoti o date mancanti).", flush=True)

    rows.sort(key=lambda x: x["completion_date_iso"], reverse=True)
    return rows


def _histlib_snapshots_complete(rw: dict) -> bool:
    """
    True solo se la riga JSON ha snapshot per-offset realmente popolati.
    Evita di trattare ``snapshots: {}`` come «completo» (altrimenti non si rivalorizza mai).
    """
    if not isinstance(rw, dict):
        return False
    snap = rw.get("snapshots")
    if not isinstance(snap, dict) or len(snap) == 0:
        return False
    for payload in snap.values():
        if not isinstance(payload, dict):
            continue
        lab = payload.get("_coverage_label")
        if isinstance(lab, str) and "/" in lab:
            try:
                a, _b = lab.split("/", 1)
                if int(a) > 0:
                    return True
            except (ValueError, TypeError):
                pass
        fn = payload.get("_coverage_found_n")
        try:
            if fn is not None and int(fn) > 0:
                return True
        except (TypeError, ValueError):
            pass
    return False


def _histlib_load_json() -> dict:
    path = pathlib.Path(MODEL_HIST_INPUT_LIB_JSON)
    if not path.exists():
        return {"schema_version": 1, "coverage_keys": list(_MODEL_HIST_COVERAGE_KEYS), "rows": {}}
    try:
        d = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(d, dict):
            raise ValueError()
        if "rows" not in d or not isinstance(d["rows"], dict):
            d["rows"] = {}
        return d
    except Exception:
        return {"schema_version": 1, "coverage_keys": list(_MODEL_HIST_COVERAGE_KEYS), "rows": {}}


def _histlib_save_json(doc: dict) -> None:
    path = pathlib.Path(MODEL_HIST_INPUT_LIB_JSON)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(doc, ensure_ascii=False, indent=2, default=str),
                    encoding="utf-8")


