def merge_by_symbol():
    yf_df         = load_json_as_df(YF_JSON)
    finnhub_df    = load_json_as_df(FINNHUB_JSON)
    variations_df = load_json_as_df(VARIATIONS_JSON)
    clinical_df   = load_excel_as_df(CLINICAL_XLSX)

    for df_name, df in {
        "yf": yf_df,
        "finnhub": finnhub_df,
        "variations": variations_df,
        "clinical": clinical_df,
    }.items():
        if df.empty:
            continue
        if "symbol" not in df.columns and "ticker" in df.columns:
            df["symbol"] = df["ticker"]
        if "symbol" not in df.columns:
            df["symbol"] = ""
        df["symbol"] = df["symbol"].astype(str).str.strip().str.upper()

    merged_df = pd.DataFrame()

    if not yf_df.empty:
        merged_df = yf_df.copy()

    if not finnhub_df.empty:
        if merged_df.empty:
            merged_df = finnhub_df.copy()
        else:
            merged_df = pd.merge(
                merged_df, finnhub_df,
                on="symbol", how="outer",
                suffixes=("", "_finnhub")
            )

    if not variations_df.empty:
        print("Variations columns loaded:", variations_df.columns.tolist())
        if merged_df.empty:
            merged_df = variations_df.copy()
        else:
            if "symbol" not in variations_df.columns:
                variations_df["symbol"] = ""
            merged_df = pd.merge(
                merged_df, variations_df,
                on="symbol", how="outer",
                suffixes=("", "_variations")
            )

        # Dopo il merge, le colonne di variations_df ottengono il suffisso "_variations"
        # SOLO se c'era una collisione di nome con merged_df (es. finnhub aveva le stesse colonne).
        # Se non c'è collisione, restano senza suffisso (es. "variation_1m_%").
        # Il foglio Financial si aspetta SEMPRE il nome con suffisso "_variations".
        # → Normalizziamo: se "variation_1m_%" esiste ma "variation_1m_%_variations" no,
        #   rinominiamo per garantire il nome atteso.
        _var_base_cols = ["variation_1m_%", "variation_3m_%", "variation_6m_%", "variation_9m_%"]
        _rename_map = {}
        for _base in _var_base_cols:
            _suffixed = f"{_base}_variations"
            if _base in merged_df.columns and _suffixed not in merged_df.columns:
                _rename_map[_base] = _suffixed
        if _rename_map:
            merged_df = merged_df.rename(columns=_rename_map)
            print(f"[merge] Rinominate colonne variazioni: {list(_rename_map.keys())} → con suffisso _variations")

    return merged_df, clinical_df


