        _L_cap = get_column_letter(SIM_COL_CAPITALE)
        _L_shr = get_column_letter(SIM_COL_AZIONI)
        _L_val = get_column_letter(SIM_COL_VALORE_ATTUALE)
        _L_pnl = get_column_letter(SIM_COL_PNL_USD)

        for _ci, _val in enumerate(vals, start=1):
            cell = ws.cell(row=rn, column=_ci)
