    def _means_only(_src: list[list[float]]) -> list[float | None]:
        out = []
        for _i in range(_cols_n):
            m, _ = _mean_sd_float(_src[_i])
            out.append(m)
        return out

    def _sds_only(_src: list[list[float]]) -> list[float | None]:
        out = []
        for _i in range(_cols_n):
            _, s = _mean_sd_float(_src[_i])
            out.append(s)
        return out

    def _ret_at_tp(dd: dict, j: int) -> float | None:
        _base = _px(dd, "close_m60", "close_m60_cal")
        if _base is None or _base <= 0:
            return None
        pri, cal = _CLOSE_SPEC[j]
        _pv = _px(dd, pri, cal)
        if _pv is None or _pv <= 0:
            return None
        return (_pv / _base - 1.0) * 100.0

    def _frac_in_global_band(keys: list[str]) -> list[float | None]:
        _out: list[float | None] = []
        for j in range(_cols_n):
            mg, sg = _means_g[j], _sds_g[j]
            if mg is None or sg is None:
                _out.append(None)
                continue
            lo, hi = mg - 2.0 * sg, mg + 2.0 * sg
            tot = hit = 0
            for k in keys:
                v = _ret_at_tp(_universe.get(k) or {}, j)
                if v is None:
                    continue
                tot += 1
                if lo <= v <= hi:
                    hit += 1
            _out.append(100.0 * hit / tot if tot else None)
        return _out

