        _aud_excel = _prev_audit_by_key.get(_pk)
        _aud_for_shrink = (
            _normalize_accuracy_audit_token(_aud_excel)
            or _normalize_accuracy_audit_token(_fb_row.get("audit")))
        _tk_disp = str(d.get("ticker") or _pk.split("|")[0]).strip()
