_BIOTECH_SYMBOLS_JSON    = os.path.join(DATA_DIR, "biotech_symbols.json")
_DISCOVERY_MARKER_FILE   = os.path.join(DATA_DIR, ".last_biotech_discovery")

# Parole chiave sufficientemente specifiche da identificare biotech/biopharma
# ma non così generiche da includere ospedali, distributori, etc.
_BIOTECH_DISCOVERY_KEYWORDS: frozenset[str] = frozenset({
    "therapeutics", "biosciences", "biopharma", "biotechnology",
    "biotherapeutics", "genomics", "oncology", "biologics",
    "biopharmaceutical", "biopharmaceuticals", "gene therapy",
    "cell therapy", "immunotherapeutics", "biotech",
    "radiotherapeutics", "radiopharmaceuticals",
})

# Caratteri non ammessi nei ticker US standard (evita preferred-share, warrants…)
import re as _re_ticker
_TICKER_RE = _re_ticker.compile(r'^[A-Z]{1,5}$')


def _auto_discover_biotech_tickers(force: bool = False) -> int:
    """
    Scopre nuovi ticker biotech leggendo il SEC EDGAR company_tickers.json
    (già in cache locale) e filtrando per parole chiave nel nome azienda.

    Eseguita automaticamente SOLO una volta al mese (primo giorno del mese,
    oppure se il marker non esiste o è di un mese precedente).
    Con force=True viene rieseguita a prescindere dalla data.

    Ritorna il numero di nuovi ticker effettivamente aggiunti.
    """
    import datetime

    today = datetime.date.today()

    # ── Controlla se è il momento di eseguire ─────────────────────────────────
    if not force:
        if os.path.exists(_DISCOVERY_MARKER_FILE):
            try:
                with open(_DISCOVERY_MARKER_FILE, encoding="utf-8") as fh:
                    last = fh.read().strip()          # formato "YYYY-MM"
                if last == today.strftime("%Y-%m"):
                    # già eseguita questo mese
                    return 0
            except Exception:
                pass
        # Esegue solo il primo giorno del mese OPPURE se marker mancante/vecchio
        if today.day != 1 and not os.path.exists(_DISCOVERY_MARKER_FILE):
            # Prima esecuzione assoluta: esegui subito per popolare il file
            pass
        elif today.day != 1:
            return 0

    print("[DISCOVERY] Avvio auto-discovery nuove biotech da SEC EDGAR…")

    # ── Carica il JSON SEC già in cache ───────────────────────────────────────
    sec_cache = os.path.join(DATA_DIR, "sec_company_tickers.json")
    if not os.path.exists(sec_cache):
        # Scarica ora tramite _load_sec_cik_map (effetto collaterale: crea il file)
        _load_sec_cik_map()
    if not os.path.exists(sec_cache):
        print("[DISCOVERY] sec_company_tickers.json non disponibile — skip.")
        return 0

    try:
        with open(sec_cache, encoding="utf-8") as fh:
            sec_data = json.load(fh)
    except Exception as exc:
        print(f"[DISCOVERY] Errore lettura sec_company_tickers.json: {exc} — skip.")
        return 0

    # ── Filtra per parole chiave nel nome azienda ─────────────────────────────
    candidates: list[str] = []
    for entry in sec_data.values():
        tk  = str(entry.get("ticker", "") or "").strip().upper()
        nm  = str(entry.get("title",  "") or "").strip().lower()
        if not tk or not nm:
            continue
        if not _TICKER_RE.match(tk):          # scarta preferred shares, warrant, etc.
            continue
        if any(kw in nm for kw in _BIOTECH_DISCOVERY_KEYWORDS):
            candidates.append(tk)

    # ── Leggi lista esistente ─────────────────────────────────────────────────
    existing: list[str] = []
    if os.path.exists(_BIOTECH_SYMBOLS_JSON):
        try:
            with open(_BIOTECH_SYMBOLS_JSON, encoding="utf-8") as fh:
                existing = json.load(fh)
        except Exception:
            pass

    existing_set = {t.upper() for t in existing}
    nuovi = sorted({t for t in candidates if t not in existing_set})

    if nuovi:
        updated = sorted(existing_set | set(nuovi))
        with open(_BIOTECH_SYMBOLS_JSON, "w", encoding="utf-8") as fh:
            json.dump(updated, fh, indent=2, ensure_ascii=False)
        preview = ", ".join(nuovi[:25]) + (f"… (+{len(nuovi)-25})" if len(nuovi) > 25 else "")
        print(f"[DISCOVERY] Aggiunti {len(nuovi)} nuovi ticker biotech: {preview}")
        print(f"[DISCOVERY] Totale ticker in biotech_symbols.json: {len(updated)}")
        try:
            from orchestrator_run_summary import record_discovery_tickers

            record_discovery_tickers(nuovi)
        except Exception:
            pass
    else:
        print("[DISCOVERY] Nessun nuovo ticker biotech trovato.")

    # ── Aggiorna marker con anno-mese corrente ────────────────────────────────
    try:
        with open(_DISCOVERY_MARKER_FILE, "w", encoding="utf-8") as fh:
            fh.write(today.strftime("%Y-%m"))
    except Exception:
        pass

    return len(nuovi)


def _sync_extra_tickers() -> int:
    """
    Legge la chiave 'extra_tickers' da retrospective_config.json e aggiunge
    i nuovi ticker a biotech_symbols.json (crea il file se non esiste).

    Ritorna il numero di ticker effettivamente aggiunti (0 = nessuna novità).
    Mostra sempre il totale attuale del file al termine.
    """
    # ── Leggi extra_tickers dalla config (file OPZIONALE) ─────────────────────
    extra: list[str] = []
    if not os.path.exists(RETRO_CONFIG_FILE):
        print(f"[INFO] {RETRO_CONFIG_FILE} non presente — nessun ticker extra da aggiungere "
              f"(file opzionale: crealo se vuoi aggiungere ticker custom o generare le sheet "
              f"'IPO Snapshot' e 'Studio').")
        return 0
    try:
        with open(RETRO_CONFIG_FILE, encoding="utf-8") as fh:
            cfg = json.load(fh)
        extra = [t.strip().upper() for t in cfg.get("extra_tickers", []) if t.strip()]
    except Exception as exc:
        print(f"[WARN] _sync_extra_tickers: errore parsing {RETRO_CONFIG_FILE}: {exc}")
        return 0

    if not extra:
        return 0

    # ── Leggi biotech_symbols.json (lista di ticker esistenti) ────────────────
    existing: list[str] = []
    if os.path.exists(_BIOTECH_SYMBOLS_JSON):
        try:
            with open(_BIOTECH_SYMBOLS_JSON, encoding="utf-8") as fh:
                existing = json.load(fh)
        except Exception as exc:
            print(f"[WARN] _sync_extra_tickers: impossibile leggere {_BIOTECH_SYMBOLS_JSON}: {exc}")

    existing_set = {t.strip().upper() for t in existing}

    # ── Trova i ticker davvero nuovi ──────────────────────────────────────────
    nuovi = [t for t in extra if t not in existing_set]

    if nuovi:
        updated = list(existing) + nuovi
        with open(_BIOTECH_SYMBOLS_JSON, "w", encoding="utf-8") as fh:
            json.dump(sorted(set(t.upper() for t in updated)), fh,
                      indent=2, ensure_ascii=False)
        print(f"[SYNC] Aggiunti {len(nuovi)} nuovi ticker a biotech_symbols.json: "
              f"{', '.join(nuovi)}")
        print(f"[SYNC] Totale ticker nel file: "
              f"{len(existing) + len(nuovi)}")
        try:
            from orchestrator_run_summary import record_extra_config_tickers

            record_extra_config_tickers(nuovi)
        except Exception:
            pass
    else:
        print(f"[SYNC] Nessun nuovo ticker da aggiungere "
              f"(extra_tickers già presenti in biotech_symbols.json).")

    return len(nuovi)


def _orch_fast_relaunch_active() -> bool:
    return os.environ.get("ORCH_FAST_RELUNCH", "").strip().lower() in (
        "1", "true", "yes", "on")


def _orch_apply_fast_relaunch_env_defaults() -> None:
    """Default «gentili» (setdefault) per iterare più velocemente su merge + Excel."""
    if not _orch_fast_relaunch_active():
        return
    os.environ.setdefault("ORCH_SKIP_FETCH", "1")
    os.environ.setdefault("ACC_SIM_IR_SCREEN_FETCH", "0")
    os.environ.setdefault("ORCH_SKIP_RETROSPECTIVE", "1")
    os.environ.setdefault("ORCH_SKIP_VARIATIONS_RETRY", "1")
    os.environ.setdefault("ORCH_SKIP_SEC_K8", "1")
    os.environ.setdefault("ORCH_SKIP_FINANCIAL_ENRICH", "1")
    os.environ.setdefault("ORCH_SKIP_LIQUIDITY_YF", "1")
    os.environ.setdefault("ORCH_SKIP_AUTO_DISCOVERY", "1")
    os.environ.setdefault("ORCH_SKIP_IMMUTABLE_INDEX", "1")


def main(skip_fetch: bool = False):
    """Pipeline completa. ``skip_fetch=True`` (``--skip-fetch`` o ``ORCH_SKIP_FETCH=1``) salta
    ``fetch_yfinance.py`` se ``data/yf.json`` esiste ed è non vuoto — utile in dev o se il fetch
    è già stato eseguito; altrimenti esce con errore.

    **Velocità / I/O:** ``ORCH_SKIP_SEC_K8=1`` salta il foglio SEC K‑8 (SEC + yfinance per coorte).
    ``ORCH_SKIP_IMMUTABLE_INDEX=1`` evita la riscrittura di ``immutable_library_index.json``.
    ``ORCH_SKIP_FINANCIAL_ENRICH=1`` salta l'arricchimento Financial (yfinance/Finnhub riga per riga).
    ``ORCH_SKIP_AUTO_DISCOVERY=1`` salta lo step mensile auto-discovery biotech da SEC.
    ``--fast-relaunch`` / ``--quick`` / ``ORCH_FAST_RELUNCH=1`` impostano default «leggeri»
    (inclusi i skip sopra dove applicabile; serve ``data/yf.json`` già popolato se skip fetch).
    ``ORCH_PERF=1`` stampa i tempi dei blocchi principali.
    """
    _orch_apply_fast_relaunch_env_defaults()
    skip_fetch = skip_fetch or os.environ.get("ORCH_SKIP_FETCH", "").strip().lower() in (
        "1", "true", "yes")
    if _orch_fast_relaunch_active():
        print(
            ">>> **Fast / quick relaunch**: ORCH_FAST_RELUNCH, --fast-relaunch o --quick "
            "(skip fetch se yf.json ok; no enrich Financial; no auto-discovery SEC; "
            "no immutable index rewrite; no HTTP IR Accuracy; no retrospective; "
            "no variations --errors-only retry; default **ORCH_SKIP_SEC_K8=1** — "
            "per SEC K‑8: `ORCH_SKIP_SEC_K8=0` prima del run). "
            "**Serve `data/yf.json` già popolato** (altrimenti step 1 da solo può superare i 5 min).",
            flush=True,
        )
    if skip_fetch:
        print(
            ">>> data_orchestrator: avvio pipeline con **skip fetch_yfinance** "
            "(serve data/yf.json già popolato) …",
            flush=True,
        )
    else:
        print(
            ">>> data_orchestrator: avvio pipeline (yfinance → fetch paralleli → merge Excel → retro) …",
            flush=True,
        )
    os.makedirs(DATA_DIR, exist_ok=True)
    try:
        from immutable_local_library import enabled_for_orchestrator, verify_and_report_startup

        if enabled_for_orchestrator():
            _skip_im_idx = os.environ.get(
                "ORCH_SKIP_IMMUTABLE_INDEX", "").strip().lower() in (
                "1", "true", "yes", "on")
            if _skip_im_idx:
                print(
                    "[ImmutableLibrary] ORCH_SKIP_IMMUTABLE_INDEX=1 — "
                    "nessuna riscrittura di immutable_library_index.json.",
                    flush=True,
                )
            verify_and_report_startup(
                DATA_DIR,
                write_index=not _skip_im_idx,
                verbose=True,
            )
    except ImportError:
        print("[ImmutableLibrary] Modulo omesso — continuo senza inventory locale.")
    except Exception as _ill_e:
        print(f"[ImmutableLibrary] Verifica disco non bloccante: {_ill_e}")

    _t_total = time.time()
    try:
        from orchestrator_run_summary import begin_orchestrator_run

        begin_orchestrator_run("weekly_full")
    except Exception:
        pass
    _perf_enabled = os.environ.get("ORCH_PERF", "").strip() == "1"

    def _perf_run(label, fn, *args, **kwargs):
        """Misura i blocchi principali quando ORCH_PERF=1."""
        if not _perf_enabled:
            return fn(*args, **kwargs)
        _t0 = time.perf_counter()
        try:
            return fn(*args, **kwargs)
        finally:
            _dt = time.perf_counter() - _t0
            print(f"[PERF] {label}: {_dt:.2f}s")

    # ── Step 0a: auto-discovery mensile nuove biotech da SEC EDGAR ────────────
    _skip_auto_disc = os.environ.get(
        "ORCH_SKIP_AUTO_DISCOVERY", "").strip().lower() in (
        "1", "true", "yes", "on")
    if not _skip_auto_disc:
        print(">>> Auto-discovery biotech (mensile)…")
        _n_disc = _perf_run("step0a auto_discovery", _auto_discover_biotech_tickers)
        if _n_disc:
            print(f"    {_n_disc} nuove società biotech aggiunte dall'universo SEC EDGAR.")
        else:
            print("    Nessun nuovo ticker da SEC EDGAR (già aggiornato questo mese).")
    else:
        print(
            ">>> ORCH_SKIP_AUTO_DISCOVERY=1: salto auto-discovery biotech (SEC).",
            flush=True,
        )

    # ── Step 0b: espande biotech_symbols.json con eventuali extra_tickers ─────
    print(">>> Sincronizzazione extra_tickers da retrospective_config.json…")
    _n_new = _perf_run("step0b sync_extra_tickers", _sync_extra_tickers)
    if _n_new:
        print(f"    {_n_new} nuovi ticker manuali aggiunti → i fetcher li scaricheranno ora.")

    # ── Step 1: yfinance (deve completare prima degli altri, produce yf.json) ──
    if skip_fetch:
        _yf_path = os.path.join(DATA_DIR, "yf.json")
        _ok_yf = os.path.isfile(_yf_path) and os.path.getsize(_yf_path) > 16
        if _ok_yf:
            print(
                f">>> Step 1 — salto fetch_yfinance (--skip-fetch / ORCH_SKIP_FETCH): uso {_yf_path}.",
                flush=True,
            )
        else:
            print(
                f"[ERROR] skip fetch attivo ma `{_yf_path}` mancante o troppo piccolo — "
                "eseguire almeno una volta senza `--skip-fetch` oppure "
                "`python fetch_yfinance.py`.",
                flush=True,
            )
            raise SystemExit(2)
    else:
        _perf_run("step1 fetch_yfinance", run_script, "fetch_yfinance.py")

    # ── Step 2: finnhub + variations + clinical in PARALLELO ──────────────────
    # I tre script sono indipendenti tra loro; leggono yf.json (già pronto).
    # Eseguirli in parallelo riduce il tempo di questa fase al più lento dei tre
    # invece della loro somma.
    _perf_run("step2 parallel_fetchers", run_scripts_parallel, [
        ("fetch_finnhub.py",                  []),
        ("fetch_variations.py",               []),
        ("BiotechClinicalTrialDataFetcher.py", []),
    ])

    # ── Step 2b: retry variations per i ticker con errore ─────────────────────
    # fetch_variations.py può salvare "No historical data" in cache se il
    # rate-limit di yfinance era ancora attivo all'inizio della fase parallela.
    # --errors-only ritenta SOLO quei ticker con force=True (bypass cache),
    # a questo punto il rate-limit si è resettato (Finnhub ha già girato 10-15min).
    _skip_vretry = os.environ.get("ORCH_SKIP_VARIATIONS_RETRY", "").strip().lower() in (
        "1", "true", "yes", "on")
    if not _skip_vretry:
        print(">>> Verifica ticker variations con errore — retry se necessario…")
        _perf_run("step2b variations_retry", run_script, "fetch_variations.py",
                  extra_args=["--errors-only"])
    else:
        print(
            ">>> ORCH_SKIP_VARIATIONS_RETRY: salto retry fetch_variations --errors-only.",
            flush=True,
        )

    # ── Step 3: merge + scrittura Excel ───────────────────────────────────────
    _t_merge = time.time()
    master_df, clinical_df = _perf_run("step3a merge_by_symbol", merge_by_symbol)
    _perf_run("step3b save_final_outputs", save_final_outputs, master_df, clinical_df)
    _perf_run("step3c print_summary", print_summary, master_df)
    print(f"    [merge + Excel completato in {time.time() - _t_merge:.0f}s]")

    # ── Step 4: Analisi retrospettiva ─────────────────────────────────────────
    # Lanciata DOPO save_final_outputs perché legge il JSON già scritto.
    _skip_retro = os.environ.get("ORCH_SKIP_RETROSPECTIVE", "").strip().lower() in (
        "1", "true", "yes", "on")
    if not _skip_retro:
        print(f"\n>>> Avvio analisi retrospettiva (finestra ±{RETRO_WINDOW_DAYS}gg)…")
        _perf_run("step4 retrospective", run_script, "fetch_retrospective.py",
                  extra_args=["--window", str(RETRO_WINDOW_DAYS)])
    else:
        print(
            "\n>>> ORCH_SKIP_RETROSPECTIVE: salto fetch_retrospective.",
            flush=True,
        )

    _elapsed = time.time() - _t_total
    print(f"\n>>> Orchestration completed successfully <<< "
          f"(totale: {_elapsed//60:.0f}m {_elapsed%60:.0f}s)")
    try:
        from orchestrator_run_summary import finalize_orchestrator_run
        from refresh_fast_status import find_latest_staged_workbook

        finalize_orchestrator_run(
            ok=True,
            elapsed_sec=_elapsed,
            staged_workbook=find_latest_staged_workbook(FINAL_XLSX),
            exit_code=0,
        )
    except Exception as _fin_e:
        print(f"[RunSummary] Riepilogo run (non bloccante): {_fin_e}", flush=True)


if _orch_invoked_as_script():
    sys.stdout.write(
        ">>> data_orchestrator: import del modulo completato — avvio main().\n",
    )
    sys.stdout.flush()
    _quick_argv = "--quick" in sys.argv[1:]
    _fast_argv = "--fast-relaunch" in sys.argv[1:] or _quick_argv
    if _fast_argv:
        sys.argv = [
            sys.argv[0],
            *[a for a in sys.argv[1:] if a not in ("--fast-relaunch", "--quick")],
        ]
        os.environ["ORCH_FAST_RELUNCH"] = "1"
    _skip_argv = "--skip-fetch" in sys.argv[1:]
    if _skip_argv:
        sys.argv = [sys.argv[0]] + [a for a in sys.argv[1:] if a != "--skip-fetch"]
    _sim_only_argv = "--simulation-only" in sys.argv[1:]
    if _sim_only_argv:
        sys.argv = [sys.argv[0]] + [a for a in sys.argv[1:] if a != "--simulation-only"]
    _sim_only_env = os.environ.get("ORCH_SIMULATION_ONLY", "").strip().lower() in (
        "1", "true", "yes",
    )
    if _sim_only_argv or _sim_only_env:
        ok = regenerate_simulation_sheet_quick()
        raise SystemExit(0 if ok else 1)
    _skip_env = os.environ.get("ORCH_SKIP_FETCH", "").strip().lower() in (
        "1", "true", "yes",
    )
    try:
        main(skip_fetch=_skip_argv or _skip_env)
    except SystemExit as _se:
        if _se.code not in (None, 0):
            try:
                from orchestrator_run_summary import finalize_orchestrator_run
                from refresh_fast_status import find_latest_staged_workbook

                finalize_orchestrator_run(
                    ok=False,
                    elapsed_sec=0,
                    staged_workbook=find_latest_staged_workbook(FINAL_XLSX),
                    exit_code=int(_se.code) if isinstance(_se.code, int) else 1,
                    error=f"exit {_se.code}",
                )
            except Exception:
                pass
        raise
    except Exception as _main_exc:
        try:
            from orchestrator_run_summary import finalize_orchestrator_run
            from refresh_fast_status import find_latest_staged_workbook

            finalize_orchestrator_run(
                ok=False,
                elapsed_sec=0,
                staged_workbook=find_latest_staged_workbook(FINAL_XLSX),
                exit_code=1,
                error=str(_main_exc),
            )
        except Exception:
            pass
        raise
    except KeyboardInterrupt:
        print(
            "\n>>> Interrotto con Ctrl+C (normale se attendevi fetch_yfinance). "
            "Per saltare lo step yfinance quando `data/yf.json` esiste già:\n"
            "    python data_orchestrator.py --skip-fetch\n"
            "    oppure:  set ORCH_SKIP_FETCH=1\n"
            "Relaunch rapido (~pochi min con yf.json già pronto; stesso profilo --quick):\n"
            "    python data_orchestrator.py --fast-relaunch\n"
            "    oppure:  set ORCH_FAST_RELUNCH=1\n"
            "Altri skip utili: ORCH_SKIP_FINANCIAL_ENRICH=1, ORCH_SKIP_SEC_K8=1, "
            "ORCH_SKIP_IMMUTABLE_INDEX=1, ORCH_PERF=1",
            flush=True,
        )
        raise SystemExit(130) from None
